# builder/gen_ch20_p3.py
# -*- coding: utf-8 -*-

exercises = [{'num': 83, 'title': 'Ловушка забытого Unlock при раннем return: дедлок и исправление через defer', 'task': '**Забытый Unlock (Deadlock)**: В упр. 284 напиши условие `if counter == 5000 { return }` внутри горутины, до `Unlock()`. Увидь, как все остальные горутины зависают навсегда.', 'theory': 'Если горутина захватывает `mu.Lock()` и выходит из функции по условию (`return`, `panic`, `break`) без вызова `mu.Unlock()`, мьютекс навсегда остается заблокированным. Все последующие горутины навсегда зависают при попытке захватить `mu.Lock()`.', 'step_by_step': '1. Продемонстрируем ошибку забытого `Unlock` при раннем выходе.\n2. Покажем, как `defer mu.Unlock()` гарантирует разблокировку.\n3. Проверим стабильное выполнение всех горутин.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype SafeRegistry struct {\n\tmu    sync.Mutex\n\titems map[int]string\n}\n\nfunc (r *SafeRegistry) Register(id int, name string) {\n\tr.mu.Lock()\n\t// ИСПРАВЛЕНИЕ: defer гарантирует вызов Unlock при любых return\n\tdefer r.mu.Unlock()\n\n\tif id == 5000 {\n\t\tfmt.Printf("[Registry] Пропуск служебного ID %d (ранний return)\\n", id)\n\t\treturn // Без defer здесь мьютекс остался бы заблокированным навсегда!\n\t}\n\n\tr.items[id] = name\n}\n\nfunc main() {\n\tregistry := &SafeRegistry{items: make(map[int]string)}\n\tvar wg sync.WaitGroup\n\n\tids := []int{100, 5000, 200, 300}\n\twg.Add(len(ids))\n\n\tfor _, id := range ids {\n\t\tgo func(targetID int) {\n\t\t\tdefer wg.Done()\n\t\t\tregistry.Register(targetID, fmt.Sprintf("Item_%d", targetID))\n\t\t}(id)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Все элементы успешно обработаны, зарегистрировано в мапе: %d\\n", len(registry.items))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Registry] Пропуск служебного ID 5000 (ранний return)\n# Все элементы успешно обработаны, зарегистрировано в мапе: 3'}], 'under_the_hood': '`defer mu.Unlock()` гарантирует освобождение семафора рантайма `runtime_Semrelease` перед выходом из кадра функции.', 'pitfalls': 'В функциях с десятками строк кода никогда не управляйте мьютексом вручную без `defer`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы главные причины утечек блокировок (Mutex Leak / Orphan Lock) в Go?»\n**Ответ:** 1) Ранний `return` по ошибке до ручного вызова `Unlock()`. 2) Неперехваченная паника (`panic`), прерывающая выполнение до `Unlock()`. Паттерн `mu.Lock(); defer mu.Unlock()` полностью устраняет обе проблемы.'}, {'num': 84, 'title': 'Управление параллельными HTTP-запросами с отменой по ошибке через errgroup.Group', 'task': 'Используйте `errgroup.Group` (из `golang.org/x/sync/errgroup`) для параллельных HTTP-запросов с обработкой первой же ошибки.', 'theory': 'Пакет `golang.org/x/sync/errgroup` расширяет функциональность `sync.WaitGroup`, добавляя:\n1. Автоматический сбор первой возникшей ошибки (`err := g.Wait()`).\n2. Привязку к контексту `context.WithCancel`: при ошибке любой горутины контекст остальных отменяется автоматически.', 'step_by_step': '1. Создадим `g, ctx := errgroup.WithContext(context.Background())`.\n2. Запустим несколько параллельных задач через `g.Go(func() error { ... })`.\n3. Дождемся результатов через `err := g.Wait()`.\n4. Обработаем первую возникшую ошибку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\n// Реализация паттерна ErrGroup без внешних зависимостей для автономности\ntype SimpleErrGroup struct {\n\twg      sync.WaitGroup\n\terrOnce sync.Once\n\terr     error\n}\n\nfunc (g *SimpleErrGroup) Go(fn func() error) {\n\tg.wg.Add(1)\n\tgo func() {\n\t\tdefer g.wg.Done()\n\t\tif err := fn(); err != nil {\n\t\t\tg.errOnce.Do(func() {\n\t\t\t\tg.err = err // Запоминаем строго первую ошибку\n\t\t\t})\n\t\t}\n\t}()\n}\n\nfunc (g *SimpleErrGroup) Wait() error {\n\tg.wg.Wait()\n\treturn g.err\n}\n\nfunc fetchService(name string, shouldFail bool) error {\n\ttime.Sleep(15 * time.Millisecond)\n\tif shouldFail {\n\t\treturn fmt.Errorf("сбой запроса к сервису \'%s\': 503 Service Unavailable", name)\n\t}\n\tfmt.Printf("[HTTP 200 OK] Сервис \'%s\' успешно ответил\\n", name)\n\treturn nil\n}\n\nfunc main() {\n\tvar g SimpleErrGroup\n\n\tg.Go(func() error { return fetchService("Auth", false) })\n\tg.Go(func() error { return fetchService("Billing", true) }) // Сбой\n\tg.Go(func() error { return fetchService("Catalog", false) })\n\n\tif err := g.Wait(); err != nil {\n\t\tfmt.Printf("\\n[ERRGROUP CATCH]: Обнаружен сбой параллельной операции: %v\\n", err)\n\t} else {\n\t\tfmt.Println("\\nВсе сервисы ответили успешно!")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# [HTTP 200 OK] Сервис 'Auth' успешно ответил\n# [HTTP 200 OK] Сервис 'Catalog' успешно ответил\n# \n# [ERRGROUP CATCH]: Обнаружен сбой параллельной операции: сбой запроса к сервису 'Billing': 503 Service Unavailable"}], 'under_the_hood': '`errgroup` внутри использует `sync.Once`, чтобы зафиксировать именно первую ошибку, вернувшуюся из набора параллельных горутин.', 'pitfalls': 'Функция в `g.Go` обязана иметь сигнатуру `func() error`. Не передавайте в неё функции, игнорирующие контекст `ctx.Done()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему errgroup.Group считается стандартом в микросервисах Go вместо ручного sync.WaitGroup?»\n**Ответ:** Потому что в реальных API параллельные запросы к сервисам (Fan-Out) всегда могут завершиться ошибкой или таймаутом. `errgroup` автоматически объединяет управление ошибками, контекст отмены и синхронизацию `WaitGroup` в единый интерфейс.'}, {'num': 85, 'title': 'Двухфазный барьер синхронизации (Barrier) на базе двух sync.WaitGroup', 'task': 'Реализуй **barrier** на `sync.WaitGroup`: N горутин должны достичь точки, прежде чем все продолжат. Используй `sync.WaitGroup` дважды: первый — достижение барьера, второй — завершение.', 'theory': 'Двухфазный барьер на `sync.WaitGroup` делит выполнение на 2 четких этапа:\n1. Фаза 1 (Сбор участников): все N горутин выполняют подготовку и вызывают `firstPhase.Done()`. Главный поток ждет `firstPhase.Wait()`.\n2. Фаза 2 (Синхронный старт): главный поток дает сигнал старта через канал или вторую фазу `secondPhase.Wait()`.', 'step_by_step': '1. Создадим `var reachBarrier sync.WaitGroup` и `var finishWork sync.WaitGroup`.\n2. Запустим 3 воркера.\n3. Дождемся сбора всех на барьере.\n4. Дождемся окончательного завершения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tconst total = 3\n\tvar reachBarrier sync.WaitGroup\n\tvar finishWork sync.WaitGroup\n\tstartSignal := make(chan struct{}) // Канал синхронного старта\n\n\treachBarrier.Add(total)\n\tfinishWork.Add(total)\n\n\tfor i := 1; i <= total; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer finishWork.Done()\n\n\t\t\t// 1. Фаза подготовки\n\t\t\ttime.Sleep(time.Duration(id*10) * time.Millisecond)\n\t\t\tfmt.Printf("[Воркер #%d] Достиг точки барьера (готов к старту)\\n", id)\n\t\t\treachBarrier.Done() // Сообщаем о достижении барьера\n\n\t\t\t// Ждем команды общего одновременного старта\n\t\t\t<-startSignal\n\n\t\t\t// 2. Фаза параллельной работы\n\t\t\tfmt.Printf(" -> [Воркер #%d] СТАРТОВАЛ одновременный забег!\\n", id)\n\t\t}(i)\n\t}\n\n\t// Ждем, пока ВСЕ 3 воркера дойдут до барьера\n\treachBarrier.Wait()\n\tfmt.Println("\\n[Main] Все 3 воркера на стартовой позиции! Даем общий сигнал старта (close channel)...")\n\tclose(startSignal) // Мгновенно разблокирует всех читателей\n\n\t// Ждем окончания работы\n\tfinishWork.Wait()\n\tfmt.Println("[Main] Все воркеры успешно финишировали!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Воркер #1] Достиг точки барьера (готов к старту)\n# [Воркер #2] Достиг точки барьера (готов к старту)\n# [Воркер #3] Достиг точки барьера (готов к старту)\n# \n# [Main] Все 3 воркера на стартовой позиции! Даем общий сигнал старта (close channel)...\n#  -> [Воркер #3] СТАРТОВАЛ одновременный забег!\n#  -> [Воркер #1] СТАРТОВАЛ одновременный забег!\n#  -> [Воркер #2] СТАРТОВАЛ одновременный забег!\n# [Main] Все воркеры успешно финишировали!'}], 'under_the_hood': 'Закрытие канала `close(startSignal)` транслируется в пробуждение всех горутин из очереди `recvq` канала за $O(N)$ времени.', 'pitfalls': 'Не отправляйте значения в канал `startSignal <- struct{}{}` в цикле — используйте `close(ch)`, так как закрытый канал моментально отдает нулевые значения всем горутинам одновременно.', 'bigtech_interview': '**Вопрос с собеседования:** «Как мгновенно разбудить 10 000 горутин одновременно одной операцией?»\n**Ответ:** Закрыть пустой сигнальный канал: `close(readyChan)`. Операция закрытия канала делает его моментально доступным для неблокирующего чтения всем горутинам без очередей.'}, {'num': 86, 'title': 'Высокоскоростной счетчик на базе sync/atomic против sync.Mutex', 'task': '**Атомарные операции (`sync/atomic`)**: Перепишите задачу на инкремент счетчика 1000 горутинами без использования мьютексов. Примените функцию `atomic.AddInt64` (или `atomic.Int64` в новых версиях Go). Сравните производительность атомиков и мьютексов.', 'theory': 'Атомарные инструкции работают на аппаратном уровне CPU (Lock-Free), избегая системных вызовов и очередей планировщика Go.', 'step_by_step': '1. Создадим переменную `var counter atomic.Int64`.\n2. Запустим 1000 горутин.\n3. Вызовем `counter.Add(1)`.\n4. Считаем результат через `counter.Load()`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n)\n\nfunc main() {\n\tvar counter atomic.Int64\n\tvar wg sync.WaitGroup\n\n\tconst total = 1000\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tcounter.Add(1) // Аппаратная атомарная операция\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Итоговое значение через atomic.Int64: %d (точно 1000)\\n", counter.Load())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Итоговое значение через atomic.Int64: 1000 (точно 1000)'}], 'under_the_hood': '`atomic.Int64.Add` генерирует машинную инструкцию `LOCK XADDQ` на x86_64.', 'pitfalls': 'Не используйте атомики для связанных изменений нескольких переменных (например, `x` и `y` координат) — атомарность гарантируется только для одной переменной.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое CAS (Compare-And-Swap) и как на нем строятся Lock-Free алгоритмы?»\n**Ответ:** CAS — процессорная инструкция `CMPXCHG`, которая атомарно сравнивает значение в памяти с ожидаемым и, если они равны, записывает новое значение. Если значение изменилось другой горутиной, CAS возвращает `false`, и алгоритм повторяет попытку в цикле (Optimistic Concurrency Control).'}, {'num': 87, 'title': 'Идиоматичная замена ручного Unlock на defer mu.Unlock()', 'task': '**Правильный `defer`**: Замени ручной вызов на `defer mu.Unlock()` сразу после `mu.Lock()`.', 'theory': 'Сравнение ручного управления блокировкой и паттерна `defer`: явный `defer` исключает человеческий фактор при рефакторинге и добавлении новых условий возврата.', 'step_by_step': '1. Создадим метод с несколькими ветками `if`.\n2. Заблокируем мьютекс и сразу напишем `defer mu.Unlock()`.\n3. Продемонстрируем надежность освобождения блокировки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype SafeStore struct {\n\tmu   sync.Mutex\n\tdata map[string]int\n}\n\nfunc (s *SafeStore) UpdateScore(player string, delta int) {\n\ts.mu.Lock()\n\tdefer s.mu.Unlock() // Золотой стандарт: блокировка освобождается при любых исходах\n\n\tif delta == 0 {\n\t\treturn // Безопасный возврат\n\t}\n\n\ts.data[player] += delta\n}\n\nfunc main() {\n\tstore := &SafeStore{data: make(map[string]int)}\n\n\tstore.UpdateScore("player1", 100)\n\tstore.UpdateScore("player1", 0) // Ранний выход\n\tstore.UpdateScore("player1", 50)\n\n\tfmt.Printf("Финальный счет player1: %d\\n", store.data["player1"])\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Финальный счет player1: 150'}], 'under_the_hood': '`defer` оптимизируется компилятором и встраивается без аллокаций в куче.', 'pitfalls': 'Не ставьте `defer mu.Unlock()` до вызова `mu.Lock()`, иначе мьютекс будет разблокирован без предварительного захвата, что вызовет панику.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему defer mu.Unlock() должен идти строго СЛЕДУЮЩЕЙ строкой после mu.Lock()?»\n**Ответ:** Чтобы между захватом мьютекса и регистрацией его освобождения не было кода, способного вызвать панику (например, разыменование nil-указателя), из-за которой мьютекс остался бы заблокированным.'}, {'num': 88, 'title': 'Неблокирующий захват мьютекса через TryLock (Go 1.18+)', 'task': 'Реализуй **"try lock"** через `sync.Mutex` + канал: `TryLock()` захватывает мьютекс с `select` и `default` (или используй `atomic` для флага). Объясни, почему в `sync.Mutex` нет встроенного `TryLock` (до Go 1.18; с 1.18 есть `TryLock()` — покажи его).', 'theory': 'Метод `mu.TryLock()` (внедрен в Go 1.18) пытается немедленно захватить мьютекс. Если мьютекс свободен, он захватывает его и возвращает `true`. Если мьютекс занят другой горутиной, `TryLock()` не блокирует поток, а мгновенно возвращает `false`.', 'step_by_step': '1. Создадим фоновый процесс, удерживающий мьютекс.\n2. Во второй горутине вызовем `mu.TryLock()`.\n3. Обработаем занятость ресурса в ветке `else`.\n4. Разберем сценарии применения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype BackgroundJobRunner struct {\n\tmu sync.Mutex\n}\n\nfunc (r *BackgroundJobRunner) RunJob(jobName string) {\n\t// Неблокирующая попытка захвата мьютекса\n\tif !r.mu.TryLock() {\n\t\tfmt.Printf("[%s] Задача пропущена: предыдущая итерация еще выполняется\\n", jobName)\n\t\treturn\n\t}\n\tdefer r.mu.Unlock()\n\n\tfmt.Printf("[%s] Старт выполнения тяжелой периодической задачи...\\n", jobName)\n\ttime.Sleep(30 * time.Millisecond)\n\tfmt.Printf("[%s] Задача успешно завершена\\n", jobName)\n}\n\nfunc main() {\n\trunner := &BackgroundJobRunner{}\n\tvar wg sync.WaitGroup\n\n\twg.Add(2)\n\n\t// Первая горутина захватывает задачу\n\tgo func() {\n\t\tdefer wg.Done()\n\t\trunner.RunJob("Task #1")\n\t}()\n\n\t// Вторая горутина пытается запуститься одновременно\n\tgo func() {\n\t\tdefer wg.Done()\n\t\ttime.Sleep(5 * time.Millisecond)\n\t\trunner.RunJob("Task #2 (параллельный запуск)")\n\t}()\n\n\twg.Wait()\n\tfmt.Println("Тестирование TryLock завершено успешно!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Task #1] Старт выполнения тяжелой периодической задачи...\n# [Task #2 (параллельный запуск)] Задача пропущена: предыдущая итерация еще выполняется\n# [Task #1] Задача успешно завершена\n# Тестирование TryLock завершено успешно!'}], 'under_the_hood': '`mu.TryLock()` выполняет единственную быструю операцию `atomic.CompareAndSwapInt32(&m.state, 0, mutexLocked)`.', 'pitfalls': 'Не стройте спинлоки на базе `for !mu.TryLock() {}` — это сжигает 100% CPU. Для ожидания используйте обычный `mu.Lock()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Где метод TryLock() оправдан в реальных проектах?»\n**Ответ:** В периодических фоновых задачах (Cron Jobs / Background Flushers): если предыдущий цикл очистки еще не завершился, следующему запуску лучше пропустить итерацию, чем выстраивать очередь из заблокированных воркеров.'}, {'num': 89, 'title': 'Моделирование Priority Inversion и честность мьютекса в Go', 'task': 'Напиши программу с **"priority inversion"** (симуляция): высокоприоритетная горутина ждёт мьютекс, захваченный низкоприоритетной. Покажи, что в Go планировщик не гарантирует приоритеты, но мьютекс fair (очередь FIFO с Go 1.19+).', 'theory': 'Инверсия приоритетов (Priority Inversion) возникает, когда важная задача не может выполниться, потому что ждет мьютекс, захваченный низкоприоритетной задачей. В Go планировщик не имеет встроенных приоритетов горутин, но режим Starvation Mode в `sync.Mutex` гарантирует честную передачу блокировки по очереди FIFO.', 'step_by_step': '1. Создадим разделяемый ресурс с `sync.Mutex`.\n2. Запустим низкоприоритетную горутину (симуляция долгой работы).\n3. Запустим высокоприоритетную задачу.\n4. Продемонстрируем порядок завершения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype SharedResource struct {\n\tmu   sync.Mutex\n\tdata string\n}\n\nfunc main() {\n\tres := &SharedResource{}\n\tvar wg sync.WaitGroup\n\n\twg.Add(2)\n\n\t// 1. Низкоприоритетная фоновая горутина\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tres.mu.Lock()\n\t\tfmt.Println("[Low-Priority Worker] Захватил мьютекс и выполняет долгий I/O...")\n\t\ttime.Sleep(30 * time.Millisecond)\n\t\tres.data = "LowPriorityResult"\n\t\tres.mu.Unlock()\n\t\tfmt.Println("[Low-Priority Worker] Мьютекс освобожден")\n\t}()\n\n\ttime.Sleep(5 * time.Millisecond)\n\n\t// 2. Высокоприоритетный запрос пользователя\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfmt.Println("[High-Priority Request] Ожидает захвата мьютекса...")\n\t\tres.mu.Lock()\n\t\tfmt.Printf("[High-Priority Request] Мьютекс получен! Данные: %s\\n", res.data)\n\t\tres.mu.Unlock()\n\t}()\n\n\twg.Wait()\n\tfmt.Println("Синхронизация завершена")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Low-Priority Worker] Захватил мьютекс и выполняет долгий I/O...\n# [High-Priority Request] Ожидает захвата мьютекса...\n# [Low-Priority Worker] Мьютекс освобожден\n# [High-Priority Request] Мьютекс получен! Данные: LowPriorityResult\n# Синхронизация завершена'}], 'under_the_hood': 'Если горутина ожидает мьютекс более 1 мс, мьютекс переключается в starvation mode, запрещая спиннинг новым горутинам.', 'pitfalls': 'Держите критические секции мьютексов максимально короткими (микросекунды, а не миллисекунды).', 'bigtech_interview': '**Вопрос с собеседования:** «Как в Go реализовать систему очередей с приоритетами задач?»\n**Ответ:** Использовать структуру данных `Priority Queue` на базе бинарной кучи `container/heap`, защищенную `sync.Mutex` или специализированным пулом воркеров.'}, {'num': 90, 'title': 'Масштабирование кэша: 100 читателей и 10 писателей на sync.RWMutex', 'task': '**RW Mutex (`sync.RWMutex`)**: Создай мапу-кэш. Запусти 100 горутин на чтение (`mu.RLock()`) и 10 на запись (`mu.Lock()`). Пойми, что `RLock` позволяет параллельное чтение, но блокирует запись.', 'theory': '`sync.RWMutex` позволяет 100 читателям одновременно находиться внутри критической секции. Когда приходит писатель, он получает монопольный доступ, приостанавливая читателей на доли миллисекунды.', 'step_by_step': '1. Создадим структуру `UserCache`.\n2. Запустим 100 горутин на чтение (`RLock`).\n3. Запустим 10 горутин на запись (`Lock`).\n4. Дождемся всех через `sync.WaitGroup`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype UserCache struct {\n\tmu    sync.RWMutex\n\tusers map[int]string\n}\n\nfunc (c *UserCache) Get(id int) string {\n\tc.mu.RLock()\n\tdefer c.mu.RUnlock()\n\treturn c.users[id]\n}\n\nfunc (c *UserCache) Set(id int, name string) {\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\tc.users[id] = name\n}\n\nfunc main() {\n\tcache := &UserCache{users: map[int]string{1: "Alice", 2: "Bob"}}\n\tvar wg sync.WaitGroup\n\n\tconst readers = 100\n\tconst writers = 10\n\n\twg.Add(readers + writers)\n\n\t// 100 читателей\n\tfor i := 0; i < readers; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\t_ = cache.Get(id % 2 + 1)\n\t\t}(i)\n\t}\n\n\t// 10 писателей\n\tfor i := 0; i < writers; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tcache.Set(id+10, fmt.Sprintf("User_%d", id))\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Все %d читателей и %d писателей успешно завершили работу без конфликтов!\\n", readers, writers)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Все 100 читателей и 10 писателей успешно завершили работу без конфликтов!'}], 'under_the_hood': '`RWMutex` в Go предотвращает Writer Starvation: ожидающий писатель блокирует последующих новых читателей.', 'pitfalls': 'Если в секции `RLock` вызвать функцию, которая попытается вызвать `Lock`, произойдет дедлок.', 'bigtech_interview': '**Вопрос с собеседования:** «Может ли горутина повысить блокировку с RLock() до Lock() (Lock Upgrade) в sync.RWMutex?»\n**Ответ:** Нет! В Go нет операции Lock Upgrade. Попытка вызвать `Lock()` при удержании `RLock()` в той же горутине гарантированно приведет к дедлоку.'}, {'num': 91, 'title': 'Классический перекрестный дедлок (Deadlock) двух мьютексов A и B', 'task': '**Классический дедлок (Deadlock)**: Создайте две горутины и два мьютекса `A` и `B`. Напишите код так, чтобы первая горутина блокировала мьютекс `A` и пыталась заблокировать `B`, а вторая горутина в это же время блокировала мьютекс `B` и пыталась заблокировать `A`. Запустите код и проанализируйте панику планировщика.', 'theory': 'Перекрестный дедлок (Deadly Embrace / Circular Wait) — классическая ошибка конкурентного программирования. Горутина 1 удерживает A и ждет B. Горутина 2 удерживает B и ждет A. Ни одна не может продолжить работу.', 'step_by_step': '1. Создадим два мьютекса `muA` и `muB`.\n2. В горутине 1 захватим `muA`, сделаем паузу и попытаемся захватить `muB`.\n3. В горутине 2 захватим `muB`, сделаем паузу и попытаемся захватить `muA`.\n4. Продемонстрируем обнаружение дедлока планировщиком.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tvar muA, muB sync.Mutex\n\tvar wg sync.WaitGroup\n\n\twg.Add(2)\n\n\t// Горутина 1: захватывает A -> затем B\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tmuA.Lock()\n\t\tfmt.Println("[G1] Захватил Mutex A...")\n\t\ttime.Sleep(10 * time.Millisecond)\n\n\t\tfmt.Println("[G1] Пытаюсь захватить Mutex B...")\n\t\tmuB.Lock() // Зависнет навсегда\n\t\tmuB.Unlock()\n\t\tmuA.Unlock()\n\t}()\n\n\t// Горутина 2: захватывает B -> затем A\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tmuB.Lock()\n\t\tfmt.Println("[G2] Захватил Mutex B...")\n\t\ttime.Sleep(10 * time.Millisecond)\n\n\t\tfmt.Println("[G2] Пытаюсь захватить Mutex A...")\n\t\tmuA.Lock() // Зависнет навсегда\n\t\tmuA.Unlock()\n\t\tmuB.Unlock()\n\t}()\n\n\twg.Wait()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [G1] Захватил Mutex A...\n# [G2] Захватил Mutex B...\n# [G1] Пытаюсь захватить Mutex B...\n# [G2] Пытаюсь захватить Mutex A...\n# fatal error: all goroutines are asleep - deadlock!\n# \n# goroutine 7 [semacquire]:\n# ...\n# goroutine 8 [semacquire]:\n# ...'}], 'under_the_hood': 'Планировщик фиксирует, что обе горутины находятся в состоянии `_Gwaiting` на семафорах друг друга.', 'pitfalls': 'Правило предотвращения дедлоков: всегда захватывайте несколько мьютексов в одном и том же глобальном порядке (Lock Ordering).', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы 4 условия возникновения дедлока Коффмана (Coffman Conditions) и как их предотвратить?»\n**Ответ:** 1) Взаимное исключение, 2) Удержание и ожидание (Hold and Wait), 3) Отсутствие вытеснения (No Preemption), 4) Круговое ожидание (Circular Wait). В Go проще всего разрушить 4-е условие с помощью строгого порядка захвата мьютексов (Global Lock Ordering).'}, {'num': 92, 'title': 'Современные типизированные атомики atomic.Int64 в Go 1.19+', 'task': 'Реализуй счётчик через `atomic.Int64` (Go 1.19+): `var counter atomic.Int64`. Методы: `counter.Add(1)`, `counter.Load()`, `counter.Store(0)`. Запусти конкурентные инкременты.', 'theory': 'Типы `atomic.Int64`, `atomic.Uint64`, `atomic.Pointer` в Go 1.19+ инкапсулируют небезопасные указатели, предоставляя безопасный ООП-интерфейс.', 'step_by_step': '1. Объявим `var counter atomic.Int64`.\n2. Запустим 500 горутин с `counter.Add(1)`.\n3. Сбросим счетчик в 0 через `counter.Store(0)`.\n4. Проверим значение через `counter.Load()`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n)\n\nfunc main() {\n\tvar counter atomic.Int64\n\tvar wg sync.WaitGroup\n\n\tconst workers = 500\n\twg.Add(workers)\n\n\tfor i := 0; i < workers; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tcounter.Add(1)\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("1. Значение счетчика после 500 инкрементов: %d\\n", counter.Load())\n\n\t// Атомарный сброс счетчика\n\tcounter.Store(0)\n\tfmt.Printf("2. Значение счетчика после Store(0): %d\\n", counter.Load())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# 1. Значение счетчика после 500 инкрементов: 500\n# 2. Значение счетчика после Store(0): 0'}], 'under_the_hood': '`atomic.Int64` содержит внутреннее неэкспортируемое поле `v int64` с гарантией выравнивания по границе 8 байт.', 'pitfalls': 'Не передавайте структуру с `atomic.Int64` по значению (`copylocks`).', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие counter.Swap(newVal) от counter.Store(newVal)?»\n**Ответ:** `Store(newVal)` просто атомарно записывает новое значение. `Swap(newVal)` атомарно записывает новое значение и **возвращает старое значение**, которое находилось в переменной до записи.'}, {'num': 93, 'title': 'Устранение Data Race в счетчике с помощью sync.Mutex', 'task': 'Исправь предыдущее задание с помощью `sync.Mutex` (`Lock()` перед инкрементом, `Unlock()` после).', 'theory': 'Защита разделяемой переменной мьютексом гарантирует строгую последовательную согласованность.', 'step_by_step': '1. Создадим переменную `var total int` и `var mu sync.Mutex`.\n2. Запустим 500 горутин.\n3. Обернем операцию в `mu.Lock()` и `mu.Unlock()`.\n4. Проверим с `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\tvar total int\n\tvar mu sync.Mutex\n\tvar wg sync.WaitGroup\n\n\tconst count = 500\n\twg.Add(count)\n\n\tfor i := 0; i < count; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tmu.Lock()\n\t\t\ttotal++\n\t\t\tmu.Unlock()\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Итоговое значение через sync.Mutex: %d\\n", total)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Итоговое значение через sync.Mutex: 500'}], 'under_the_hood': '`sync.Mutex` сериализует операции, устраняя конкуренцию на уровне кэш-линий памяти.', 'pitfalls': 'Для простых числовых счетчиков `atomic` предпочтительнее мьютексов по скорости и объему кода.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда Mutex лучше Atomic, а когда наоборот?»\n**Ответ:** `Atomic` идеален для простых скаляров (счетчики метрик, флаги). `Mutex` необходим, когда нужно атомарно изменить несколько связанных полей (например, баланс счета и статус транзакции) или защитить сложные структуры (мапы, срезы).'}, {'num': 94, 'title': 'Исправление состояния гонки через низкоуровневый atomic.AddInt64', 'task': '**Исправление через `sync/atomic`**: Убери мьютексы. Замени `counter` на `var counter int64`. Используй `atomic.AddInt64(&counter, 1)` в горутинах. Сравни скорость (в уме: атомики сильно быстрее мьютексов для простых счетчиков).', 'theory': 'Использование функций `atomic.AddInt64(&val, delta)` и `atomic.LoadInt64(&val)` обеспечивает максимальную производительность без создания объектов мьютексов.', 'step_by_step': '1. Создадим переменную `var counter int64`.\n2. Запустим 1000 горутин.\n3. Вызовем `atomic.AddInt64(&counter, 1)`.\n4. Считаем результат через `atomic.LoadInt64(&counter)`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n)\n\nfunc main() {\n\tvar counter int64\n\tvar wg sync.WaitGroup\n\n\tconst total = 1000\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tatomic.AddInt64(&counter, 1)\n\t\t}()\n\t}\n\n\twg.Wait()\n\tval := atomic.LoadInt64(&counter)\n\tfmt.Printf("Итоговое значение (atomic.AddInt64): %d\\n", val)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Итоговое значение (atomic.AddInt64): 1000'}], 'under_the_hood': '`atomic.AddInt64` возвращает новое значение после инкремента: `newVal := atomic.AddInt64(&c, 1)`.', 'pitfalls': 'Чтение `counter` без `atomic.LoadInt64(&counter)` по-прежнему является состоянием гонки! Читать нужно также через atomic.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему прямое чтение val := counter после завершения wg.Wait() без atomic.Load безопасно, а во время работы горутин — нет?»\n**Ответ:** Вызов `wg.Wait()` создает отношение Happens-Before: все записи из горутин до `wg.Done()` гарантированно становятся видны в потоке после `wg.Wait()`. Во время же работы горутин барьера нет, поэтому требуется `atomic.Load`.'}, {'num': 95, 'title': 'Lock-Free стек Трейбера (Treiber Stack) на базе atomic.Pointer (Go 1.19+)', 'task': 'Реализуй **lock-free стек** через `atomic.Pointer` (Go 1.19+): `type Node[T any] struct { value T; next atomic.Pointer[Node[T]] }`. Методы `Push` и `Pop` через `atomic.CompareAndSwapPointer` (или `CompareAndSwap` в `atomic.Pointer`).', 'theory': 'Стек Трейбера (Treiber Stack) — классическая Lock-Free структура данных. Операции `Push` и `Pop` выполняются без единого мьютекса в цикле оптимистичной фиксации CAS (Compare-And-Swap) через `atomic.Pointer[Node[T]]`.', 'step_by_step': '1. Объявим структуру узла `Node[T any]` и стека `LockFreeStack[T any]`.\n2. Реализуем метод `Push(val T)` через `head.CompareAndSwap`.\n3. Реализуем метод `Pop() (T, bool)` через `head.CompareAndSwap`.\n4. Проверим параллельный Push/Pop из 100 горутин.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n)\n\ntype Node[T any] struct {\n\tvalue T\n\tnext  *Node[T]\n}\n\ntype LockFreeStack[T any] struct {\n\thead atomic.Pointer[Node[T]]\n}\n\nfunc (s *LockFreeStack[T]) Push(value T) {\n\tnewNode := &Node[T]{value: value}\n\tfor {\n\t\toldHead := s.head.Load()\n\t\tnewNode.next = oldHead\n\t\t// Атомарная попытка переставить вершину стека\n\t\tif s.head.CompareAndSwap(oldHead, newNode) {\n\t\t\treturn\n\t\t}\n\t}\n}\n\nfunc (s *LockFreeStack[T]) Pop() (T, bool) {\n\tfor {\n\t\toldHead := s.head.Load()\n\t\tif oldHead == nil {\n\t\t\tvar zero T\n\t\t\treturn zero, false // Стек пуст\n\t\t}\n\t\tnewHead := oldHead.next\n\t\t// Атомарная попытка сдвинуть вершину стека\n\t\tif s.head.CompareAndSwap(oldHead, newHead) {\n\t\t\treturn oldHead.value, true\n\t\t}\n\t}\n}\n\nfunc main() {\n\tstack := &LockFreeStack[int]{}\n\tvar wg sync.WaitGroup\n\n\tconst totalItems = 100\n\twg.Add(totalItems)\n\n\t// Конкурентный Push\n\tfor i := 1; i <= totalItems; i++ {\n\t\tgo func(val int) {\n\t\t\tdefer wg.Done()\n\t\t\tstack.Push(val)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\n\t// Извлечение всех элементов\n\tpoppedCount := 0\n\tfor {\n\t\t_, ok := stack.Pop()\n\t\tif !ok {\n\t\t\tbreak\n\t\t}\n\t\tpoppedCount++\n\t}\n\n\tfmt.Printf("Успешно помещено и извлечено %d элементов из Lock-Free стека!\\n", poppedCount)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Успешно помещено и извлечено 100 элементов из Lock-Free стека!'}], 'under_the_hood': '`atomic.Pointer[T].CompareAndSwap` выполняет атомарное сравнение 64-битного адреса указателя в памяти.', 'pitfalls': 'В языках C/C++ стек Трейбера подвержен проблеме ABA. В Go благодаря Automatic Memory Management (GC) память узла не переиспользуется под другой объект, пока на него есть живая ссылка `oldHead`, устраняя классическую проблему ABA.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go Lock-Free стек Трейбера не страдает от фатальной ошибки ABA-problem как в C++?»\n**Ответ:** Потому что GC в Go не освобождает память узла `oldHead`, пока локальная переменная горутины держит на него ссылку. Адрес памяти не может быть перевыделен под совершенно другой узел во время работы CAS-цикла.'}, {'num': 96, 'title': 'Утечка горутин при блокировке на небуферизованном канале без читателя', 'task': '**Утечка горутин (Goroutine Leak)**: Напишите функцию, которая запускает горутину, ожидающую запись в небуферизованный канал. Однако функция завершается раньше, и никто никогда в этот канал ничего не запишет. Объясните, почему запущенная горутина останется в памяти навсегда и как такие утечки могут исчерпать ресурсы сервера.', 'theory': 'Небуферизованный канал требует одновременного присутствия и писателя, и читателя (Rendezvous). Если вызывающая функция завершается без чтения, горутина-писатель навсегда блокируется в состоянии `_Gwaiting`.', 'step_by_step': '1. Создадим функцию с ошибкой утечки `leakQuery()`.\n2. Замерим количество горутин до и после вызова.\n3. Продемонстрируем исправление через буферизованный канал `make(chan Result, 1)`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"runtime"\n\t"time"\n)\n\nfunc queryFirstFastest() string {\n\t// ОШИБКА: небуферизованный канал!\n\t// Медленная горутина навсегда зависнет на ch <- result\n\tch := make(chan string)\n\n\tgo func() {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tch <- "Быстрый ответ"\n\t}()\n\n\tgo func() {\n\t\ttime.Sleep(50 * time.Millisecond)\n\t\tch <- "Медленный ответ" // УТЕЧКА: никто никогда не прочитает!\n\t}()\n\n\t// Читаем только первый ответ и выходим\n\treturn <-ch\n}\n\nfunc main() {\n\tfmt.Printf("1. Горутин до вызова: %d\\n", runtime.NumGoroutine())\n\n\t_ = queryFirstFastest()\n\n\ttime.Sleep(70 * time.Millisecond)\n\tfmt.Printf("2. Горутин после вызова: %d (1 горутина утекла навсегда!)\\n", runtime.NumGoroutine())\n\tfmt.Println("ИСПРАВЛЕНИЕ: использовать буферизованный канал make(chan string, 2)")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Горутин до вызова: 1\n# 2. Горутин после вызова: 2 (1 горутина утекла навсегда!)\n# ИСПРАВЛЕНИЕ: использовать буферизованный канал make(chan string, 2)'}], 'under_the_hood': 'Заблокированная горутина удерживает ссылки на стек, аргументы и канал, блокируя освобождение памяти сборщиком мусора.', 'pitfalls': 'При паттерне Fan-Out всегда делайте размер буфера канала равным количеству запускаемых горутин: `make(chan Result, numWorkers)`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы три главные причины утечек горутин в продакшене?»\n**Ответ:** 1) Запись в небуферизованный канал без читателя при раннем выходе/таймауте. 2) Чтение из канала, в который никто никогда не запишет и не закроет его. 3) Зависание на сетевом I/O без `context.WithTimeout`.'}, {'num': 97, 'title': 'Атомарное обновление сложной структуры конфигурации через atomic.Value', 'task': 'Напиши программу с `atomic.Value`. Сохрани в неё `config struct{ Host string; Port int }`. Покажи, что `atomic.Value` позволяет **атомарно** заменить конфиг целиком. Читатели получают либо старую, либо новую версию, но не "смешанную".', 'theory': '`atomic.Value` предоставляет атомарное чтение и запись значений произвольного типа `any` без блокировок. Это идеальный инструмент для горячей перезагрузки конфигурации (Hot Reload) под высокой нагрузкой.', 'step_by_step': '1. Создадим структуру `ServerConfig struct { Host string; Port int }`.\n2. Создадим `var cfgHolder atomic.Value`.\n3. Запишем начальную конфигурацию через `cfgHolder.Store(...)`.\n4. Запустим читателей и в фоне атомарно обновим конфигурацию на лету.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n\t"time"\n)\n\ntype ServerConfig struct {\n\tHost string\n\tPort int\n}\n\nfunc main() {\n\tvar cfgHolder atomic.Value\n\n\t// 1. Инициализация начальной версии конфигурации\n\tinitialCfg := ServerConfig{Host: "127.0.0.1", Port: 8080}\n\tcfgHolder.Store(initialCfg)\n\n\tvar wg sync.WaitGroup\n\twg.Add(2)\n\n\t// Читатель\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor i := 0; i < 4; i++ {\n\t\t\tcfg := cfgHolder.Load().(ServerConfig)\n\t\t\tfmt.Printf("[Reader] Актуальный конфиг: %s:%d\\n", cfg.Host, cfg.Port)\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t}\n\t}()\n\n\t// Писатель (горячая перезагрузка)\n\tgo func() {\n\t\tdefer wg.Done()\n\t\ttime.Sleep(15 * time.Millisecond)\n\t\tfmt.Println("\\n[Reload] Атомарная перезагрузка конфигурации на лету...")\n\t\tnewCfg := ServerConfig{Host: "0.0.0.0", Port: 9000}\n\t\tcfgHolder.Store(newCfg) // Атомарная замена без мьютексов\n\t}()\n\n\twg.Wait()\n\tfmt.Println("\\nВсе чтения выполнены консистентно!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Reader] Актуальный конфиг: 127.0.0.1:8080\n# [Reader] Актуальный конфиг: 127.0.0.1:8080\n# \n# [Reload] Атомарная перезагрузка конфигурации на лету...\n# [Reader] Актуальный конфиг: 0.0.0.0:9000\n# [Reader] Актуальный конфиг: 0.0.0.0:9000\n# \n# Все чтения выполнены консистентно!'}], 'under_the_hood': '`atomic.Value` внутри хранит пару `(typ unsafe.Pointer, data unsafe.Pointer)` и использует атомарную инструкцию синхронизации указателей.', 'pitfalls': 'В `atomic.Value` нельзя передавать `nil` и нельзя менять тип сохраняемого объекта после первого `Store` (это вызовет немедленную панику).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему atomic.Value.Store(nil) вызывает панику?»\n**Ответ:** Потому что `Store` извлекает конкретный тип интерфейса `any` и фиксирует его в поле `typ`. `nil` не имеет типа, и рантайм Go не может гарантировать типобезопасность последующих чтений.'}, {'num': 98, 'title': 'Типобезопасная замена конфигурации на лету через atomic.Pointer[T]', 'task': '**Сложный атомик (Atomic Pointer)**: В Go 1.19+ используй `atomic.Pointer[T]` для безопасной замены целой структуры конфигурации на лету без блокировок.', 'theory': '`atomic.Pointer[T]` — это дженерик-версия атомарного указателя, устраняющая необходимость использования `atomic.Value` и ручного приведения типов `.(T)`.', 'step_by_step': '1. Создадим структуру `ClusterTopology`.\n2. Создадим переменную `var currentTopology atomic.Pointer[ClusterTopology]`.\n3. Сохраним указатель через `currentTopology.Store(&ClusterTopology{...})`.\n4. Продемонстрируем типобезопасное чтение `currentTopology.Load()`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n\t"time"\n)\n\ntype ClusterTopology struct {\n\tPrimaryNode  string\n\tReplicaNodes []string\n}\n\nfunc main() {\n\tvar topologyHolder atomic.Pointer[ClusterTopology]\n\n\t// Начальная топология\n\ttopologyHolder.Store(&ClusterTopology{\n\t\tPrimaryNode:  "db-node-01.prod",\n\t\tReplicaNodes: []string{"db-replica-01.prod"},\n\t})\n\n\tvar wg sync.WaitGroup\n\twg.Add(2)\n\n\t// Читатели\n\tgo func() {\n\t\tdefer wg.Done()\n\t\ttopo := topologyHolder.Load()\n\t\tfmt.Printf("[Read 1] Primary: %s, Replicas: %v\\n", topo.PrimaryNode, topo.ReplicaNodes)\n\t}()\n\n\t// Писатель (Failover переключение мастера)\n\tgo func() {\n\t\tdefer wg.Done()\n\t\ttime.Sleep(5 * time.Millisecond)\n\t\tnewTopo := &ClusterTopology{\n\t\t\tPrimaryNode:  "db-replica-01.prod (Promoted to Master)",\n\t\t\tReplicaNodes: []string{"db-node-02.prod"},\n\t\t}\n\t\ttopologyHolder.Store(newTopo)\n\t\tfmt.Println("[Failover] Топология кластера атомарно обновлена!")\n\t}()\n\n\twg.Wait()\n\tfinalTopo := topologyHolder.Load()\n\tfmt.Printf("[Final Topo] Активный мастер: %s\\n", finalTopo.PrimaryNode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Read 1] Primary: db-node-01.prod, Replicas: [db-replica-01.prod]\n# [Failover] Топология кластера атомарно обновлена!\n# [Final Topo] Активный мастер: db-replica-01.prod (Promoted to Master)'}], 'under_the_hood': '`atomic.Pointer[T]` напрямую выполняет атомарные инструкции `atomic.StorePointer` и `atomic.LoadPointer` на уровне процессора.', 'pitfalls': 'Никогда не мутируйте поля структуры, полученной из `topologyHolder.Load()` — всегда создавайте новый объект и заменяйте указатель целиком (Copy-On-Write).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему Copy-On-Write через atomic.Pointer[T] идеален для маршрутизации сетевого трафика?»\n**Ответ:** Потому что миллионы сетевых запросов в секунду могут считывать таблицу маршрутов без единой блокировки (`0 ns latency overhead`), а фоновые обновления таблицы происходят атомарной сменой одного 64-битного указателя.'}, {'num': 99, 'title': 'Реализация легковесного Spin-Lock на atomic.Bool и runtime.Gosched()', 'task': 'Напиши **spin-lock** через `atomic.Bool`: `for !lock.CompareAndSwap(false, true) { runtime.Gosched() }`. Объясни, когда spin-lock уместен (короткие критические секции), а когда лучше `sync.Mutex`.', 'theory': 'Spin-Lock — это примитив блокировки, который непрерывно проверяет условие освобождения в цикле активного ожидания (Busy-Wait). `runtime.Gosched()` уступает квант времени другим горутинам, предотвращая 100% сжигание ядра процессора.', 'step_by_step': '1. Создадим структуру `SpinLock struct { locked atomic.Bool }`.\n2. Реализуем метод `Lock()` с циклом `for !l.locked.CompareAndSwap(false, true) { runtime.Gosched() }`.\n3. Реализуем метод `Unlock()` с `l.locked.Store(false)`.\n4. Проверим защиту инкремента.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"runtime"\n\t"sync"\n\t"sync/atomic"\n)\n\ntype SpinLock struct {\n\tlocked atomic.Bool\n}\n\nfunc (l *SpinLock) Lock() {\n\t// Активное ожидание освобождения блокировки с уступкой кванта\n\tfor !l.locked.CompareAndSwap(false, true) {\n\t\truntime.Gosched() // Передаем управление другим горутинам\n\t}\n}\n\nfunc (l *SpinLock) Unlock() {\n\tl.locked.Store(false)\n}\n\nfunc main() {\n\tvar spin SpinLock\n\tvar counter int\n\tvar wg sync.WaitGroup\n\n\tconst total = 500\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tspin.Lock()\n\t\t\tcounter++ // Сверхкороткая критическая секция\n\t\t\tspin.Unlock()\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Итоговое значение через SpinLock: %d (из 500)\\n", counter)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Итоговое значение через SpinLock: 500 (из 500)'}], 'under_the_hood': '`CompareAndSwap` пытается атомарно перевести флаг из `false` в `true`. Если другая горутина уже захватила блокировку, CAS возвращает `false`.', 'pitfalls': 'Spin-Lock категорически запрещено использовать для долгих операций (I/O, долгие вычисления) — это приведет к деградации планировщика.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в стандартной библиотеке Go нет публичного SpinLock?»\n**Ответ:** Потому что стандартный `sync.Mutex` в Go уже является адаптивным гибридом: он сначала спинит несколько циклов на CPU (Active Spin), а если блокировка не освобождается, переводит горутину в системный сон на семафоре (Passive Wait).'}, {'num': 100, 'title': 'Lock-Free счетчик на 1 000 000 операций: atomic.AddInt64', 'task': 'Используй `sync/atomic` для lock-free счётчика: `atomic.AddInt64(&counter, 1)`. Запусти 1M инкрементов из 100 горутин. Сравни производительность с `sync.Mutex`.', 'theory': 'Тестирование $1\\,000\\,000$ операций инкремента на `atomic.AddInt64`: аппаратная атомарность без создания объектов мьютексов.', 'step_by_step': '1. Создадим переменную `var counter int64`.\n2. Запустим 100 горутин по 10 000 инкрементов.\n3. Вызовем `atomic.AddInt64(&counter, 1)`.\n4. Проверим с `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n)\n\nfunc main() {\n\tvar counter int64\n\tvar wg sync.WaitGroup\n\n\tconst goroutines = 100\n\tconst opsPerGoroutine = 10000\n\n\twg.Add(goroutines)\n\tfor i := 0; i < goroutines; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tfor j := 0; j < opsPerGoroutine; j++ {\n\t\t\t\tatomic.AddInt64(&counter, 1)\n\t\t\t}\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfinalCount := atomic.LoadInt64(&counter)\n\tfmt.Printf("Итоговое значение Lock-Free счетчика: %d (ровно 1 000 000)\\n", finalCount)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Итоговое значение Lock-Free счетчика: 1000000 (ровно 1 000 000)'}], 'under_the_hood': '`atomic.AddInt64` выполняется процессором через lock-free шину кэш-когерентности MESI.', 'pitfalls': 'При сверхвысокой конкуренции на одном адресе памяти кэш-линия постоянно прыгает между ядрами CPU (Cache Bouncing).', 'bigtech_interview': '**Вопрос с собеседования:** «Что быстрее при 1M инкрементов из 100 горутин: sync.Mutex или atomic.AddInt64?»\n**Ответ:** `atomic.AddInt64` быстрее в 3–5 раз, так как не производит усыпления горутин в планировщике и не выделяет структуры синхронизации в куче.'}, {'num': 101, 'title': 'Инициализация конфигурации синглтона 100 горутинами через sync.Once', 'task': '**Синглтон через `sync.Once`**: Напиши функцию `InitConfig()`. Создай `var once sync.Once`. В цикле запусти 100 горутин, каждая вызывает `once.Do(InitConfig)`. Убедись, что инициализация отработала ровно **один** раз.', 'theory': '`sync.Once` гарантирует атомарность первичной инициализации для любого количества параллельных клиентов.', 'step_by_step': '1. Создадим функцию `InitConfig()`.\n2. Создадим `var once sync.Once` и счетчик реальных запусков `initCalls`.\n3. Запустим 100 горутин с `once.Do(InitConfig)`.\n4. Проверим, что `initCalls == 1`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nvar (\n\tonce      sync.Once\n\tinitCalls int\n)\n\nfunc InitConfig() {\n\tinitCalls++\n\tfmt.Println("[InitConfig] Тяжелая инициализация глобальных параметров приложения...")\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst total = 100\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tonce.Do(InitConfig)\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Все %d горутин обратились к инициализации. Реальных запусков функции: %d\\n", total, initCalls)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [InitConfig] Тяжелая инициализация глобальных параметров приложения...\n# Все 100 горутин обратились к инициализации. Реальных запусков функции: 1'}], 'under_the_hood': '`once.Do` выполняет двойную проверку (Double-Checked Locking) с барьером памяти.', 'pitfalls': 'Не передавайте `sync.Once` по значению.', 'bigtech_interview': '**Вопрос с собеседования:** «Может ли горутина прочитать полуинициализированный объект при использовании sync.Once?»\n**Ответ:** НЕТ! Метод `Do()` блокирует все остальные горутины на мьютексе `o.m` до тех пор, пока инициализирующая функция полностью не завершит выполнение. Барьер памяти гарантирует полную видимость всех полей объекта.'}, {'num': 102, 'title': 'Ловушка двойного Lock: дедлок из-за отсутствия реентерабельности мьютексов', 'task': '**[Каверзный кейс]**: Попробуй заблокировать `Mutex`, который уже заблокирован этой же горутиной (двойной Lock). Поймай дедлок. (В Go нет реентерабельных мьютексов).', 'theory': 'В Go мьютексы не имеют понятия владельца. Повторный вызов `Lock()` из того же потока пытается захватить уже заблокированный семафор, вызывая дедлок.', 'step_by_step': '1. Создадим мьютекс `var mu sync.Mutex`.\n2. Захватим его первый раз `mu.Lock()`.\n3. Продемонстрируем неблокирующую проверку `mu.TryLock() == false`.\n4. Объясним архитектурные причины.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\tvar mu sync.Mutex\n\n\tfmt.Println("1. Первый захват mu.Lock()...")\n\tmu.Lock()\n\tfmt.Println("   Мьютекс успешно заблокирован.")\n\n\tfmt.Println("2. Проверка повторного захвата через TryLock()...")\n\tif !mu.TryLock() {\n\t\tfmt.Println("   TryLock вернул false: мьютекс уже заблокирован!")\n\t\tfmt.Println("   Внимание: вызов обычного mu.Lock() здесь вызвал бы фатальный дедлок!")\n\t}\n\n\tmu.Unlock()\n\tfmt.Println("3. Мьютекс успешно освобожден.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Первый захват mu.Lock()...\n#    Мьютекс успешно заблокирован.\n# 2. Проверка повторного захвата через TryLock()...\n#    TryLock вернул false: мьютекс уже заблокирован!\n#    Внимание: вызов обычного mu.Lock() здесь вызвал бы фатальный дедлок!\n# 3. Мьютекс успешно освобожден.'}], 'under_the_hood': '`sync.Mutex` в Go намеренно спроектирован без хранения Goroutine ID для минимального размера (8 байт) и максимальной скорости.', 'pitfalls': 'Если структуре требуется вызывать свои методы, разделяйте их на публичные с блокировкой и приватные `*Locked()` без нее.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go нет реентерабельных мьютексов?»\n**Ответ:** Потому что рекурсивные мьютексы маскируют нарушение инвариантов и усложняют код. В Go поощряется явное проектирование критических секций.'}, {'num': 103, 'title': 'Модель памяти Go (Memory Model): гарантии Happens-Before и барьеры памяти', 'task': 'Напиши программу с `atomic.AddUint64` и **memory ordering**: покажи, что атомарные операции гарантируют **happens-before** отношения между горутинами. Без `atomic` (или `sync`) компилятор может переупорядочить инструкции.', 'theory': 'Модель памяти Go (Go Memory Model) определяет правила, при которых чтение переменной в одной горутине гарантированно видит запись, сделанную другой горутиной. Атомарные операции пакета `sync/atomic` создают отношение строгого порядка выполнения (Happens-Before) и аппаратные барьеры памяти (Memory Barriers).', 'step_by_step': '1. Создадим разделяемые данные `data string` и флаг готовности `var ready atomic.Bool`.\n2. В горутине запишем данные и установим `ready.Store(true)`.\n3. В читателе дождемся флага `ready.Load()`.\n4. Убедимся, что данные гарантированно прочитаны.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"runtime"\n\t"sync"\n\t"sync/atomic"\n)\n\nvar (\n\tpayload string\n\tready   atomic.Bool\n)\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\twg.Add(2)\n\n\t// Писатель\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tpayload = "Sensitive Transaction Payload" // 1. Запись данных\n\t\tready.Store(true)                        // 2. Атомарный барьер памяти Happens-Before\n\t}()\n\n\t// Читатель\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor !ready.Load() { // 3. Атомарная проверка\n\t\t\truntime.Gosched()\n\t\t}\n\t\t// 4. Гарантированно видим payload\n\t\tfmt.Printf("[Reader] Успешно получены данные: %s\\n", payload)\n\t}()\n\n\twg.Wait()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Reader] Успешно получены данные: Sensitive Transaction Payload'}], 'under_the_hood': '`ready.Store(true)` запрещает компилятору и CPU переносить инструкцию записи `payload` ниже атомарного сохранения флага (Release Semantics).', 'pitfalls': 'Без `atomic` компилятор может переупорядочить инструкции (Instruction Reordering), и читатель увидит `ready == true`, но пустой `payload`!', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое отношение Happens-Before в спецификации Go Memory Model?»\n**Ответ:** Это частичный порядок выполнения операций. Если событие $A$ happens-before события $B$, то результат операции $A$ гарантированно завершен и виден операции $B$. Синхронизация через каналы, мьютексы, `WaitGroup` и `atomic` устанавливает Happens-Before.'}, {'num': 104, 'title': 'Lock-Free вычисление максимума UpdateMax через цикл CAS на atomic.Int64', 'task': 'Реализуй **lock-free max** через `atomic.Int64`: `UpdateMax(newVal int64)` атомарно обновляет значение, только если `newVal > current`. Используй цикл `for` с `Load` и `CompareAndSwap`.', 'theory': 'Паттерн CAS-Loop (цикл Compare-And-Swap):\n1. Считываем текущее значение `curr := val.Load()`.\n2. Проверяем бизнес-условие: если `newVal <= curr`, выходим.\n3. Пытаемся атомарно записать: `if val.CompareAndSwap(curr, newVal) { return }`.\n4. Если параллельная горутина успела изменить значение, повторяем цикл.', 'step_by_step': '1. Создадим структуру `AtomicMax struct { max atomic.Int64 }`.\n2. Реализуем метод `UpdateMax(newVal int64)`.\n3. Запустим 100 горутин со случайными значениями.\n4. Проверим точное максимальное значение.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n)\n\ntype AtomicMax struct {\n\tval atomic.Int64\n}\n\nfunc (m *AtomicMax) UpdateMax(newVal int64) {\n\tfor {\n\t\tcurrent := m.val.Load()\n\t\tif newVal <= current {\n\t\t\treturn // Новое значение меньше или равно текущему максимуму\n\t\t}\n\t\t// Пытаемся атомарно заменить current на newVal\n\t\tif m.val.CompareAndSwap(current, newVal) {\n\t\t\treturn // Успешное обновление\n\t\t}\n\t\t// Если CAS вернул false, повторяем цикл с новым актуальным current\n\t}\n}\n\nfunc (m *AtomicMax) Get() int64 {\n\treturn m.val.Load()\n}\n\nfunc main() {\n\ttracker := &AtomicMax{}\n\tvar wg sync.WaitGroup\n\n\tvalues := []int64{15, 82, 43, 994, 210, 550, 994, 12}\n\twg.Add(len(values))\n\n\tfor _, v := range values {\n\t\tgo func(val int64) {\n\t\t\tdefer wg.Done()\n\t\t\ttracker.UpdateMax(val)\n\t\t}(v)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Итоговый глобальный максимум (Lock-Free): %d (из 994)\\n", tracker.Get())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Итоговый глобальный максимум (Lock-Free): 994 (из 994)'}], 'under_the_hood': 'CAS-цикл выполняется полностью без блокировки потоков ОС (Lock-Free Progress Guarantee).', 'pitfalls': 'Если критическая секция сложная, CAS-цикл может голодать при высокой конкуренции. Для простых операций (Max, Min) CAS идеален.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие Lock-Free от Wait-Free алгоритмов?»\n**Ответ:** Lock-Free гарантирует, что хотя бы один поток в системе делает прогресс за конечное число шагов. Wait-Free гарантирует, что абсолютно каждый поток завершит операцию за ограниченное число шагов.'}, {'num': 105, 'title': 'Базовые операции sync.Map: Store, Load, LoadOrStore и Delete', 'task': '**Базовый `sync.Map`**: Когда нужна конкурентная мапа (много горутин читают и пишут), используй `sync.Map`. Попробуй методы `Store`, `Load`, `LoadOrStore` и `Delete`.', 'theory': 'Практикум по всем 4 ключевым методам `sync.Map`:\n1. `Store(key, value)` — сохранить пару ключ-значение.\n2. `Load(key)` — прочитать значение.\n3. `LoadOrStore(key, value)` — атомарно вернуть старое или записать новое.\n4. `Delete(key)` — удалить ключ.', 'step_by_step': '1. Создадим `var m sync.Map`.\n2. Продемонстрируем `Store` и `Load`.\n3. Продемонстрируем работу `LoadOrStore`.\n4. Продемонстрируем `Delete`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\tvar m sync.Map\n\n\t// 1. Store & Load\n\tm.Store("server_name", "app-backend-01")\n\tval, ok := m.Load("server_name")\n\tfmt.Printf("1. Load: val=%v, ok=%v\\n", val, ok)\n\n\t// 2. LoadOrStore (ключ уже есть -> вернет старое значение, loaded = true)\n\tactual1, loaded1 := m.LoadOrStore("server_name", "NEW_NAME")\n\tfmt.Printf("2. LoadOrStore (существующий): actual=%v, loaded=%v\\n", actual1, loaded1)\n\n\t// 3. LoadOrStore (ключа нет -> запишет новое, loaded = false)\n\tactual2, loaded2 := m.LoadOrStore("port", 8080)\n\tfmt.Printf("3. LoadOrStore (новый): actual=%v, loaded=%v\\n", actual2, loaded2)\n\n\t// 4. Delete\n\tm.Delete("server_name")\n\t_, exists := m.Load("server_name")\n\tfmt.Printf("4. После Delete(\'server_name\'): exists=%v\\n", exists)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# 1. Load: val=app-backend-01, ok=true\n# 2. LoadOrStore (существующий): actual=app-backend-01, loaded=true\n# 3. LoadOrStore (новый): actual=8080, loaded=false\n# 4. После Delete('server_name'): exists=false"}], 'under_the_hood': '`LoadOrStore` использует атомарные указатели на структуру `entry`, исключая дублирование записи.', 'pitfalls': 'В Go 1.20+ добавлены методы `Swap` и `CompareAndSwap` для `sync.Map`.', 'bigtech_interview': '**Вопрос с собеседования:** «Что делает метод m.CompareAndDelete(key, oldVal) в sync.Map (Go 1.20+)?»\n**Ответ:** Атомарно удаляет запись по ключу `key` только в том случае, если её текущее значение равно `oldVal`.'}, {'num': 106, 'title': 'Инкапсуляция sync.Mutex в структуру счетчика: Increment() и Value()', 'task': 'Создай структуру-счетчик с полем `count` и встроенным `sync.Mutex`. Напиши методы `Increment()` и `Value()`.', 'theory': 'Встраивание (embedding) `sync.Mutex` в структуру позволяет вызывать `c.Lock()` напрямую. Однако чаще делают поле мьютекса неэкспортируемым `mu sync.Mutex` для сокрытия деталей блокировки.', 'step_by_step': '1. Создадим структуру `Counter struct { mu sync.Mutex; count int }`.\n2. Реализуем метод `Increment()`.\n3. Реализуем метод `Value() int`.\n4. Протестируем в 100 горутинах.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype Counter struct {\n\tmu    sync.Mutex\n\tcount int\n}\n\nfunc (c *Counter) Increment() {\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\tc.count++\n}\n\nfunc (c *Counter) Value() int {\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\treturn c.count\n}\n\nfunc main() {\n\tc := &Counter{}\n\tvar wg sync.WaitGroup\n\n\tconst total = 100\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tc.Increment()\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Итоговое значение счетчика: %d\\n", c.Value())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Итоговое значение счетчика: 100'}], 'under_the_hood': '`c.mu.Lock()` защищает поле `count` от конфликтов на шине памяти.', 'pitfalls': 'Всегда объявляйте методы на pointer receiver `(c *Counter)`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему встраивание (anonymous embedding) sync.Mutex в структуру считается спорной практикой?»\n**Ответ:** Потому что методы `Lock()` и `Unlock()` становятся публичными методами внешней структуры, позволяя любому стороннему пакету заблокировать ваш внутренний мьютекс и вызвать дедлок. Лучше объявлять приватное поле `mu sync.Mutex`.'}, {'num': 107, 'title': 'Сравнение проблемы ABA в C++ и Go: влияние сборщика мусора (GC)', 'task': 'Напиши программу с `atomic.Pointer` и **ABA-problem**: покажи, что `CompareAndSwap` может "пропустить" изменение, если указатель вернулся к тому же значению. Обсуди, почему в Go managed memory это менее критично, чем в C++.', 'theory': 'Проблема ABA возникает в Lock-Free алгоритмах: 1) Поток считывает указатель $A$, 2) Другой поток меняет на $B$, затем возвращает на $A$ (но с другим содержимым), 3) Первый поток выполняет CAS($A$, $C$), успешно меняя указатель, но нарушая инвариант. В Go GC не переиспользует память старого $A$, пока есть ссылка, снижая риск повреждения структур.', 'step_by_step': '1. Создадим структуру `DataNode struct { val string }`.\n2. Создадим `var ptr atomic.Pointer[DataNode]`.\n3. Смоделируем сценарий смены $A \\to B \\to A$.\n4. Объясним различия с языками без сборщика мусора.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync/atomic"\n)\n\ntype ConfigState struct {\n\tVersion int\n\tName    string\n}\n\nfunc main() {\n\tvar ptr atomic.Pointer[ConfigState]\n\n\tnodeA := &ConfigState{Version: 1, Name: "Alpha"}\n\tnodeB := &ConfigState{Version: 2, Name: "Beta"}\n\n\tptr.Store(nodeA)\n\n\t// 1. Поток 1 считывает nodeA\n\tobserved := ptr.Load()\n\tfmt.Printf("1. Поток 1 прочитал указатель A: %+v (адрес: %p)\\n", observed, observed)\n\n\t// 2. Поток 2 меняет A -> B -> A\n\tptr.Store(nodeB)\n\tfmt.Printf("2. Поток 2 заменил на B: %+v\\n", ptr.Load())\n\tptr.Store(nodeA)\n\tfmt.Printf("3. Поток 2 вернул назад указатель A: %+v\\n", ptr.Load())\n\n\t// 3. Поток 1 делает CAS в предположении, что изменений не было\n\tnodeC := &ConfigState{Version: 3, Name: "Gamma"}\n\tswapped := ptr.CompareAndSwap(observed, nodeC)\n\n\tfmt.Printf("4. Результат CAS(observed, nodeC): %v (указатель совпадал, CAS успешен)\\n", swapped)\n\tfmt.Printf("5. Итоговое состояние: %+v\\n", ptr.Load())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Поток 1 прочитал указатель A: &{Version:1 Name:Alpha} (адрес: 0x...)\n# 2. Поток 2 заменил на B: &{Version:2 Name:Beta}\n# 3. Поток 2 вернул назад указатель A: &{Version:1 Name:Alpha}\n# 4. Результат CAS(observed, nodeC): true (указатель совпадал, CAS успешен)\n# 5. Итоговое состояние: &{Version:3 Name:Gamma}'}], 'under_the_hood': 'В C++ память $A$ могла быть освобождена через `free()` и выделена заново под новый объект с тем же адресом. В Go $A$ не удаляется из памяти, пока `observed` держит ссылку.', 'pitfalls': 'Если сам объект $A$ является мутабельным, его внутренние поля могли измениться во время $A \\to B \\to A$.', 'bigtech_interview': '**Вопрос с собеседования:** «Как решается проблема ABA в C++ и почему в Go она встречается реже?»\n**Ответ:** В C++ используют Tagged Pointers (Double-Word CAS со счетчиком версий или `std::atomic<std::shared_ptr>`). В Go автоматическое управление памятью (Garbage Collector) исключает повторное перевыделение одного адреса памяти под другой тип объекта во время удержания ссылки.'}, {'num': 108, 'title': 'Одноразовый сигнальный флаг (One-Shot Signal) на atomic.Bool', 'task': 'Напиши **"one-shot"** сигнал через `atomic.Bool`: `var ready atomic.Bool`. Горутина-продюсер делает `ready.Store(true)` после инициализации. Потребители ждут в цикле `for !ready.Load() { runtime.Gosched() }`. Покажи, что это работает без mutex.', 'theory': 'Одноразовый сигнал готовности (One-Shot Signal) через `atomic.Bool` — сверхлегкая альтернатива мьютексам для сценариев инициализации ресурсов.', 'step_by_step': '1. Создадим `var ready atomic.Bool`.\n2. Запустим 3 потребителей с циклом `for !ready.Load() { runtime.Gosched() }`.\n3. Продюсер подготовит данные и сделает `ready.Store(true)`.\n4. Потребители моментально продолжат работу.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"runtime"\n\t"sync"\n\t"sync/atomic"\n\t"time"\n)\n\nfunc main() {\n\tvar ready atomic.Bool\n\tvar wg sync.WaitGroup\n\n\tconst consumers = 3\n\twg.Add(consumers)\n\n\t// Потребители\n\tfor i := 1; i <= consumers; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tfmt.Printf("[Потребитель #%d] Ожидание готовности системы...\\n", id)\n\t\t\tfor !ready.Load() {\n\t\t\t\truntime.Gosched() // Уступаем процессор\n\t\t\t}\n\t\t\tfmt.Printf(" -> [Потребитель #%d] Сигнал получен! Старт работы.\\n", id)\n\t\t}(i)\n\t}\n\n\ttime.Sleep(15 * time.Millisecond)\n\n\t// Продюсер\n\tfmt.Println("\\n[Продюсер] Инициализация завершена. Отправка сигнала ready.Store(true)...")\n\tready.Store(true)\n\n\twg.Wait()\n\tfmt.Println("[Main] Все потребители успешно отработали!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Потребитель #1] Ожидание готовности системы...\n# [Потребитель #2] Ожидание готовности системы...\n# [Потребитель #3] Ожидание готовности системы...\n# \n# [Продюсер] Инициализация завершена. Отправка сигнала ready.Store(true)...\n#  -> [Потребитель #1] Сигнал получен! Старт работы.\n#  -> [Потребитель #3] Сигнал получен! Старт работы.\n#  -> [Потребитель #2] Сигнал получен! Старт работы.\n# [Main] Все потребители успешно отработали!'}], 'under_the_hood': '`ready.Store(true)` выполняет атомарный барьер памяти, мгновенно уведомляя кэши всех ядер CPU.', 'pitfalls': 'Для долгих ожиданий (секунды/минуты) лучше использовать `close(chan struct{})`, чтобы спящие горутины не занимали процессорное время.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда atomic.Bool лучше канала close(ch) для сигнала старта?»\n**Ответ:** Когда задержка уведомления должна быть минимальной (наносекунды) в High-Frequency Trading (HFT) или ядре сетевого драйвера, где переключение контекста канала избыточно дорого.'}, {'num': 109, 'title': 'Безопасная итерация по sync.Map с помощью метода Range', 'task': '**Обход `sync.Map`**: Используй метод `Range` для итерации по `sync.Map`. Обрати внимание, что он принимает callback-функцию.', 'theory': 'Метод `sm.Range(func(key, value any) bool)` выполняет последовательный обход элементов мапы. Если callback-функция возвращает `false`, итерация немедленно прекращается.', 'step_by_step': '1. Заполним `sync.Map` элементами.\n2. Реализуем полный обход всех ключей.\n3. Реализуем ранний выход при нахождении нужного элемента.\n4. Проверим результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\tvar sm sync.Map\n\n\tsm.Store("USD", 92.5)\n\tsm.Store("EUR", 99.8)\n\tsm.Store("CNY", 12.8)\n\tsm.Store("GBP", 118.2)\n\n\t// 1. Полный обход всех валют\n\tfmt.Println("=== 1. Полный список курсов валют ===")\n\tsm.Range(func(key, value any) bool {\n\t\tfmt.Printf("Валюта: %-4s = %.2f руб.\\n", key.(string), value.(float64))\n\t\treturn true // Продолжаем обход\n\t})\n\n\t// 2. Поиск с ранним выходом (break)\n\tfmt.Println("\\n=== 2. Поиск первой валюты дороже 100 руб. ===")\n\tsm.Range(func(key, value any) bool {\n\t\trate := value.(float64)\n\t\tif rate > 100.0 {\n\t\t\tfmt.Printf("Найдена дорогая валюта: %s (%.2f руб.) -> прерываем обход\\n", key.(string), rate)\n\t\t\treturn false // Прерываем итерацию\n\t\t}\n\t\treturn true\n\t})\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === 1. Полный список курсов валют ===\n# Валюта: USD  = 92.50 руб.\n# Валюта: EUR  = 99.80 руб.\n# Валюта: CNY  = 12.80 руб.\n# Валюта: GBP  = 118.20 руб.\n# \n# === 2. Поиск первой валюты дороже 100 руб. ===\n# Найдена дорогая валюта: GBP (118.20 руб.) -> прерываем обход'}], 'under_the_hood': 'Метод `Range` в `sync.Map` фиксирует снимок `read` мапы или выполняет промоушен `dirty` мапы перед обходом.', 'pitfalls': 'Метод `Range` не гарантирует консистентный моментальный снимок (Snapshot), если во время итерации другие горутины параллельно вызывают `Store`/`Delete`.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова временная сложность метода Range в sync.Map?»\n**Ответ:** В лучшем случае $O(N)$ по `read` мапе без блокировок. В худшем (если было много записей новых ключей) $O(N)$ с захватом мьютекса для копирования `dirty` мапы в `read`.'}, {'num': 110, 'title': 'Многопоточный кэш с раздельными блокировками RLock и Lock', 'task': 'Используй `sync.RWMutex`. Создай мапу. Несколько горутин читают из мапы (`RLock`), и одна периодически пишет (`Lock`). Убедись, что чтение не блокирует само себя.', 'theory': 'Демонстрация работы `sync.RWMutex`: горутины чтения выполняются параллельно, а писатель периодически обновляет данные.', 'step_by_step': '1. Создадим структуру `StatsStore`.\n2. Реализуем `GetStat(metric string) int` с `mu.RLock()`.\n3. Реализуем `SetStat(metric string, val int)` с `mu.Lock()`.\n4. Запустим читателей и писателя.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype StatsStore struct {\n\tmu    sync.RWMutex\n\tstats map[string]int\n}\n\nfunc (s *StatsStore) Get(metric string) int {\n\ts.mu.RLock()\n\tdefer s.mu.RUnlock()\n\treturn s.stats[metric]\n}\n\nfunc (s *StatsStore) Set(metric string, val int) {\n\ts.mu.Lock()\n\tdefer s.mu.Unlock()\n\ts.stats[metric] = val\n}\n\nfunc main() {\n\tstore := &StatsStore{stats: map[string]int{"rps": 1500}}\n\tvar wg sync.WaitGroup\n\n\twg.Add(3)\n\n\t// Читатель 1\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tval := store.Get("rps")\n\t\tfmt.Printf("[R1] Текущий RPS: %d\\n", val)\n\t}()\n\n\t// Читатель 2\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tval := store.Get("rps")\n\t\tfmt.Printf("[R2] Текущий RPS: %d\\n", val)\n\t}()\n\n\t// Периодический писатель\n\tgo func() {\n\t\tdefer wg.Done()\n\t\ttime.Sleep(5 * time.Millisecond)\n\t\tstore.Set("rps", 2200)\n\t\tfmt.Println("[Writer] RPS обновлен до 2200")\n\t}()\n\n\twg.Wait()\n\tfmt.Printf("Финальный RPS в хранилище: %d\\n", store.Get("rps"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [R1] Текущий RPS: 1500\n# [R2] Текущий RPS: 1500\n# [Writer] RPS обновлен до 2200\n# Финальный RPS в хранилище: 2200'}], 'under_the_hood': '`sync.RWMutex` позволяет читателям `R1` и `R2` работать без задержек.', 'pitfalls': 'Не забывайте `defer s.mu.RUnlock()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Что произойдет, если горутина вызовет RUnlock() дважды?»\n**Ответ:** Произойдет паника `panic: sync: RUnlock of unlocked RWMutex`, так как внутренний счетчик читателей станет отрицательным.'}, {'num': 111, 'title': 'Пул тяжелых структур с фабричной функцией New в sync.Pool', 'task': '**Повторное использование с `sync.Pool`**: Создай пул тяжелых структур `pool := &sync.Pool{ New: func() any { return new(HeavyObject) } }`. Забирай объекты `pool.Get()`, работай с ними и возвращай `pool.Put()`.', 'theory': 'Фабричная функция `New` вызывается автоматически, когда в пуле нет доступных свободных объектов. Метод `Put(obj)` возвращает память в пул для последующих запросов.', 'step_by_step': '1. Создадим тяжелую структуру `WorkerContext`.\n2. Создадим `var contextPool sync.Pool`.\n3. В горутине запросим объект через `pool.Get()`.\n4. Очистим и вернем через `defer pool.Put()`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype HeavyContext struct {\n\tScratchpad [16 * 1024]byte\n\tRequestID  string\n}\n\nfunc (h *HeavyContext) Reset() {\n\th.RequestID = ""\n}\n\nvar ctxPool = sync.Pool{\n\tNew: func() any {\n\t\treturn new(HeavyContext)\n\t},\n}\n\nfunc handleRequest(reqID string) {\n\tctx := ctxPool.Get().(*HeavyContext)\n\tctx.Reset()\n\tdefer ctxPool.Put(ctx)\n\n\tctx.RequestID = reqID\n\tctx.Scratchpad[0] = 0xFF\n\tfmt.Printf("[Handler] Обработан запрос: %s\\n", ctx.RequestID)\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst total = 3\n\twg.Add(total)\n\n\tfor i := 1; i <= total; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\thandleRequest(fmt.Sprintf("req_id_%d", id))\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("Обработка через sync.Pool завершена успешно!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Handler] Обработан запрос: req_id_3\n# [Handler] Обработан запрос: req_id_1\n# [Handler] Обработан запрос: req_id_2\n# Обработка через sync.Pool завершена успешно!'}], 'under_the_hood': '`sync.Pool` локализует объекты по потокам P, снижая конкуренцию на глобальной блокировке.', 'pitfalls': 'Обязательно очищайте поля `Reset()` перед использованием.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в New функции sync.Pool возвращают указатель new(T), а не значение T?»\n**Ответ:** Потому что возврат значения приводит к боксингу в `any` (Heap Allocation на каждый `Get`/`Put`), сводя на нет всю пользу от пулинга. Указатель передается по ссылке без скрытых аллокаций.'}, {'num': 112, 'title': 'Устранение деградации False Sharing через байтовый паддинг (CPU Cache-Line Padding)', 'task': 'Напиши программу с **"false sharing"**: два `atomic.Int64` на соседних полях одной структуры. Запусти две горутины, каждая инкрементирует свой счётчик. Покажи, что из-за кэш-линии (64 байта) они конкурируют за одну линию. Исправь через **padding** (`_ [56]byte` между полями).', 'theory': 'Ложное разделение (False Sharing) возникает, когда две независимые переменные, модифицируемые разными ядрами CPU, случайно попадают в одну 64-байтную кэш-линию L1/L2. Протокол MESI вынужден непрерывно инвалидировать кэш обоих ядер (Cache Bouncing). Паддинг `[56]byte` разносит переменные по разным кэш-линиям.', 'step_by_step': '1. Создадим структуру `PaddedCounters` с выравниванием `_ [56]byte`.\n2. Запустим 2 горутины, каждая инкрементирует свой изолированный счетчик.\n3. Продемонстрируем независимость ядер CPU.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n\t"time"\n)\n\n// Структура с защитой от False Sharing через 64-байтный паддинг\ntype PaddedCounters struct {\n\tcounterA atomic.Int64 // 8 байт\n\t_        [56]byte     // Паддинг для заполнения 64-байтной кэш-линии\n\tcounterB atomic.Int64 // 8 байт (начинается в СЛЕДУЮЩЕЙ кэш-линии)\n}\n\nfunc main() {\n\tvar c PaddedCounters\n\tvar wg sync.WaitGroup\n\n\tconst ops = 1000000\n\tstart := time.Now()\n\twg.Add(2)\n\n\t// Ядро 1: работает строго с counterA\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor i := 0; i < ops; i++ {\n\t\t\tc.counterA.Add(1)\n\t\t}\n\t}()\n\n\t// Ядро 2: работает строго с counterB\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor i := 0; i < ops; i++ {\n\t\t\tc.counterB.Add(1)\n\t\t}\n\t}()\n\n\twg.Wait()\n\tfmt.Printf("Время параллельного счета с CPU Padding: %v\\n", time.Since(start))\n\tfmt.Printf("Счетчик A: %d, Счетчик B: %d\\n", c.counterA.Load(), c.counterB.Load())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Время параллельного счета с CPU Padding: 9.85ms\n# Счетчик A: 1000000, Счетчик B: 1000000'}], 'under_the_hood': 'Размер кэш-линии в современных процессорах x86_64 и ARM64 составляет ровно 64 байта. 8 байт `Int64` + 56 байт массива = ровно 64 байта.', 'pitfalls': 'Паддинг увеличивает размер структур в памяти. Применяйте его только в критических HighLoad счетчиках.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое False Sharing и как его обнаружить в Go?»\n**Ответ:** Это падение производительности из-за конкуренции разных процессорных ядер за одну 64-байтную кэш-линию. Обнаруживается профилировщиком аппаратных счетчиков `perf c2c` (Cache-to-Cache) в Linux.'}, {'num': 113, 'title': 'Статический запрет копирования структур с Mutex: анализ go vet', 'task': '**[Каверзный кейс]**: Скопируй структуру, содержащую `sync.Mutex`, в другую переменную. Передай копию в горутину и вызови `Lock()`. Запусти `go vet` и пойми, почему копировать мьютексы нельзя (и как исправить — передавать по указателю).', 'theory': 'Копирование структуры с `sync.Mutex` копирует внутреннее битовое состояние замка. Блокировка копии не защищает оригинальную структуру, приводя к Data Race. `go vet` отслеживает такие ошибки через анализатор `copylocks`.', 'step_by_step': '1. Создадим структуру `SafeConfig struct { mu sync.Mutex; data string }`.\n2. Напишем функцию с правильной передачей по указателю `*SafeConfig`.\n3. Запустим проверку `go vet` и саму программу.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype SafeConfig struct {\n\tmu   sync.Mutex\n\tdata string\n}\n\n// ПРАВИЛЬНО: передача по указателю *SafeConfig\nfunc updateConfig(cfg *SafeConfig, val string, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tcfg.mu.Lock()\n\tdefer cfg.mu.Unlock()\n\tcfg.data = val\n}\n\nfunc main() {\n\tcfg := &SafeConfig{data: "Initial"}\n\tvar wg sync.WaitGroup\n\n\twg.Add(1)\n\tgo updateConfig(cfg, "Updated Value", &wg)\n\n\twg.Wait()\n\tfmt.Printf("Конфигурация успешно обновлена: %s\\n", cfg.data)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go vet main.go\ngo run -race main.go\n# Вывод:\n# Конфигурация успешно обновлена: Updated Value'}], 'under_the_hood': '`go vet` проверяет тип аргументов функций: при обнаружении структуры со встроенным `sync.Mutex` выдается ошибка `passes lock by value`.', 'pitfalls': 'Никогда не возвращайте структуры с мьютексом по значению из конструкторов (возвращайте `*MyStruct`).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему конструкторы структур с Mutex всегда возвращают *MyStruct, а не MyStruct?»\n**Ответ:** Чтобы исключить копирование мьютекса при присваивании результата вызова конструктора `cfg := NewConfig()` переменной.'}, {'num': 114, 'title': 'Синхронный старт пула из 10 воркеров через sync.Cond и Broadcast()', 'task': '**Условные переменные (`sync.Cond`)**: Создай `cond := sync.NewCond(&sync.Mutex{})`. 10 воркеров вызывают `cond.Wait()` (ожидая старта). В `main` вызови `cond.Broadcast()`, чтобы мгновенно разбудить их всех.', 'theory': '`cond.Broadcast()` — самый быстрый способ одновременного старта группы из N горутин после завершения фазы инициализации.', 'step_by_step': '1. Создадим `var mu sync.Mutex` и `cond := sync.NewCond(&mu)`.\n2. Запустим 10 воркеров с ожиданием `for !started { cond.Wait() }`.\n3. В `main` установим `started = true` и вызовем `cond.Broadcast()`.\n4. Дождемся завершения через `sync.WaitGroup`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tvar mu sync.Mutex\n\tcond := sync.NewCond(&mu)\n\tstarted := false\n\n\tvar wg sync.WaitGroup\n\tconst totalWorkers = 5\n\n\tfor i := 1; i <= totalWorkers; i++ {\n\t\twg.Add(1)\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\n\t\t\tmu.Lock()\n\t\t\tfor !started {\n\t\t\t\tcond.Wait()\n\t\t\t}\n\t\t\tmu.Unlock()\n\n\t\t\tfmt.Printf("[Воркер #%d] Мгновенно проснулся по Broadcast!\\n", id)\n\t\t}(i)\n\t}\n\n\ttime.Sleep(20 * time.Millisecond)\n\n\tmu.Lock()\n\tfmt.Println("[Main] Подготовка завершена. Отправка сигнала Broadcast()...\\n")\n\tstarted = true\n\tcond.Broadcast()\n\tmu.Unlock()\n\n\twg.Wait()\n\tfmt.Println("\\n[Main] Все воркеры успешно завершили работу!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Main] Подготовка завершена. Отправка сигнала Broadcast()...\n# \n# [Воркер #5] Мгновенно проснулся по Broadcast!\n# [Воркер #1] Мгновенно проснулся по Broadcast!\n# [Воркер #2] Мгновенно проснулся по Broadcast!\n# [Воркер #3] Мгновенно проснулся по Broadcast!\n# [Воркер #4] Мгновенно проснулся по Broadcast!\n# \n# [Main] Все воркеры успешно завершили работу!'}], 'under_the_hood': '`Broadcast()` перемещает все горутины из очереди условной переменной в очередь связанного мьютекса.', 'pitfalls': 'Обязательно освобождайте мьютекс `mu.Unlock()` сразу после выхода из цикла ожидания `cond.Wait()`.', 'bigtech_interview': '**Вопрос с собеседования:** «В каком порядке просыпаются горутины при вызове cond.Broadcast()?»\n**Ответ:** Порядок пробуждения и захвата мьютекса не детерминирован и зависит от очередности планировщика Go.'}, {'num': 115, 'title': 'Рефакторинг: замена Mutex на atomic.AddInt64 для простого счетчика', 'task': 'Используй `sync/atomic` пакет: замени `Mutex` на `atomic.AddInt64` для счетчика. Оцени разницу в синтаксисе.', 'theory': 'Рефакторинг от `sync.Mutex` к `sync/atomic` сокращает объем кода с 4 строк (`mu.Lock(); counter++; mu.Unlock()`) до одной компактной строки `atomic.AddInt64(&counter, 1)`.', 'step_by_step': '1. Объявим `var counter int64`.\n2. Запустим конкурентные инкременты.\n3. Считаем результат через `atomic.LoadInt64`.\n4. Сравним читаемость.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n)\n\nfunc main() {\n\tvar totalRequests int64\n\tvar wg sync.WaitGroup\n\n\tconst requests = 300\n\twg.Add(requests)\n\n\tfor i := 0; i < requests; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\t// Лаконично и lock-free\n\t\t\tatomic.AddInt64(&totalRequests, 1)\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Всего запросов обработано: %d\\n", atomic.LoadInt64(&totalRequests))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Всего запросов обработано: 300'}], 'under_the_hood': '`atomic.AddInt64` не использует структуры данных в куче.', 'pitfalls': 'Не забывайте передавать адрес переменной `&totalRequests`.', 'bigtech_interview': '**Вопрос с собеседования:** «Можно ли атомарно уменьшить значение счетчика с помощью atomic.AddInt64?»\n**Ответ:** Да, передав отрицательное число: `atomic.AddInt64(&counter, -1)`.'}, {'num': 116, 'title': 'Ловушка передачи структуры с Mutex по значению (passes lock by value)', 'task': '**Каверзный случай: Копирование Mutex**: Передай структуру, содержащую `sync.Mutex`, в функцию по значению. Используй `go vet` — он покажет ошибку "locks by value". Никогда не копируй мьютексы!', 'theory': 'При передаче структуры с `sync.Mutex` по значению создается независимый клон замка. Захват блокировки в копии не защищает данные в исходной структуре.', 'step_by_step': '1. Создадим функцию с правильной передачей указателя `*SafeWallet`.\n2. Объясним правило статического анализатора `go vet`.\n3. Проверим отсутствие предупреждений.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype SafeWallet struct {\n\tmu      sync.Mutex\n\tbalance int\n}\n\n// ПРАВИЛЬНО: передача *SafeWallet по указателю\nfunc addFunds(w *SafeWallet, amount int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tw.mu.Lock()\n\tdefer w.mu.Unlock()\n\tw.balance += amount\n}\n\nfunc main() {\n\twallet := &SafeWallet{balance: 100}\n\tvar wg sync.WaitGroup\n\n\twg.Add(2)\n\tgo addFunds(wallet, 50, &wg)\n\tgo addFunds(wallet, 50, &wg)\n\n\twg.Wait()\n\tfmt.Printf("Баланс кошелька: %d руб. (go vet copylocks: OK)\\n", wallet.balance)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go vet main.go\ngo run -race main.go\n# Вывод:\n# Баланс кошелька: 200 руб. (go vet copylocks: OK)'}], 'under_the_hood': '`go vet` содержит правило `copylocks`, анализирующее типы параметров в сигнатурах функций.', 'pitfalls': 'Если сделать `wallet2 := *wallet`, произойдет неявное копирование мьютекса.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему компилятор Go разрешает копирование структур с мьютексами, а go vet ругается?»\n**Ответ:** Язык Go придерживается строгой ортогональности спецификации: компилятор не накладывает искусственных ограничений на семантику типов-значений. Проверки архитектурных правил вынесены в линтеры.'}, {'num': 117, 'title': 'Потокобезопасный Lazy Singleton подключения к кэшу через sync.Once', 'task': 'Создай объект-одиночку (Singleton) с отложенной инициализацией (lazy loading) с использованием `sync.Once`.', 'theory': 'Отложенная инициализация (Lazy Loading) позволяет отложить тяжелое создание сетевых клиентов до момента, когда они действительно понадобятся в рантайме.', 'step_by_step': '1. Создадим структуру `RedisClient`.\n2. Реализуем функцию `GetRedis() *RedisClient` с `sync.Once`.\n3. Запустим 10 горутин, запрашивающих клиент.\n4. Убедимся в однократной инициализации.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype RedisClient struct {\n\tEndpoint string\n}\n\nvar (\n\tredisInstance *RedisClient\n\tredisOnce     sync.Once\n)\n\nfunc GetRedis() *RedisClient {\n\tredisOnce.Do(func() {\n\t\tfmt.Println("[REDIS] Подключение к Redis Cluster (Lazy Init)...")\n\t\tredisInstance = &RedisClient{Endpoint: "redis://10.0.0.1:6379"}\n\t})\n\treturn redisInstance\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst total = 5\n\twg.Add(total)\n\n\tfor i := 1; i <= total; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tclient := GetRedis()\n\t\t\t_ = client.Endpoint\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Клиент Redis готов к работе: %s\\n", GetRedis().Endpoint)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [REDIS] Подключение к Redis Cluster (Lazy Init)...\n# Клиент Redis готов к работе: redis://10.0.0.1:6379'}], 'under_the_hood': '`redisOnce.Do` исключает повторные захваты мьютексов после первичной инициализации.', 'pitfalls': 'Не вызывайте `GetRedis()` внутри самой функции инициализации `redisOnce.Do`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие Eager Initialization от Lazy Initialization синглтона в Go?»\n**Ответ:** Eager инициализируется в функции `init()` при старте приложения (замедляет холодный старт и тратит память, если ресурс не пригодится). Lazy инициализируется через `sync.Once` строго при первом реальном вызове.'}, {'num': 118, 'title': 'Фиксация состояния sync.Once при панике и невозможность повторного вызова', 'task': '**[Каверзный кейс]**: Внутри `sync.Once.Do(func())` вызови панику. Вызови `Do` еще раз с другой функцией. Убедись, что `Once` запомнил вызов, и вторая функция не выполнится, несмотря на панику.', 'theory': 'Экспериментальное доказательство: `sync.Once` защищен блоком `defer`, поэтому паника внутри функции `Do` не сбрасывает флаг `done`.', 'step_by_step': '1. Создадим `var once sync.Once`.\n2. Вызовем `once.Do` с паникой и перехватим через `recover()`.\n3. Попробуем вызвать `once.Do` повторно.\n4. Убедимся, что вторая функция не запустилась.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\tvar once sync.Once\n\n\t// 1. Первый вызов с паникой\n\tfunc() {\n\t\tdefer func() {\n\t\t\tif r := recover(); r != nil {\n\t\t\t\tfmt.Printf("[1] Перехвачена паника: %v\\n", r)\n\t\t\t}\n\t\t}()\n\n\t\tonce.Do(func() {\n\t\t\tfmt.Println("[1] Старт функции 1 -> паника!")\n\t\t\tpanic("сбой инициализации БД")\n\t\t})\n\t}()\n\n\t// 2. Второй вызов с другой функцией\n\tsecondRan := false\n\tonce.Do(func() {\n\t\tsecondRan = true\n\t\tfmt.Println("[2] Этот текст никогда не будет напечатан")\n\t})\n\n\tfmt.Printf("[2] Вторая функция выполнилась: %v (Once считает себя завершенным)\\n", secondRan)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [1] Старт функции 1 -> паника!\n# [1] Перехвачена паника: сбой инициализации БД\n# [2] Вторая функция выполнилась: false (Once считает себя завершенным)'}], 'under_the_hood': '`defer atomic.StoreUint32(&o.done, 1)` выполняется при раскрутке стека во время паники.', 'pitfalls': 'Если при инициализации возможна штатная ошибка (например, нет сети), используйте кастомную обертку с возвратом `error`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как написать sync.OnceWithError, который повторяет попытку при err != nil?»\n**Ответ:** Реализовать структуру с `sync.Mutex`: захватывать `mu.Lock()`, проверять `if initialized { return nil }`, вызывать `err := fn()`, и только если `err == nil`, устанавливать `initialized = true`.'}, {'num': 119, 'title': 'Параллельная обработка задач с обработкой первой ошибки через errgroup', 'task': 'Используйте пакет `golang.org/x/sync/errgroup`. Запустите группу горутин, которые могут вернуть ошибку.', 'theory': '`errgroup.Group` позволяет запускать набор горутин `g.Go(fn)` и собирать первую возвращенную ошибку в `g.Wait()`.', 'step_by_step': '1. Создадим структуру `ErrGroup`.\n2. Запустим 3 горутины, одна из которых вернет ошибку.\n3. Дождемся завершения в `g.Wait()`.\n4. Проверим перехват ошибки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype MinimalErrGroup struct {\n\twg   sync.WaitGroup\n\tonce sync.Once\n\terr  error\n}\n\nfunc (g *MinimalErrGroup) Go(fn func() error) {\n\tg.wg.Add(1)\n\tgo func() {\n\t\tdefer g.wg.Done()\n\t\tif err := fn(); err != nil {\n\t\t\tg.once.Do(func() {\n\t\t\t\tg.err = err\n\t\t\t})\n\t\t}\n\t}()\n}\n\nfunc (g *MinimalErrGroup) Wait() error {\n\tg.wg.Wait()\n\treturn g.err\n}\n\nfunc main() {\n\tvar g MinimalErrGroup\n\n\tg.Go(func() error {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\treturn nil\n\t})\n\n\tg.Go(func() error {\n\t\ttime.Sleep(15 * time.Millisecond)\n\t\treturn errors.New("ошибка валидации данных пользователя")\n\t})\n\n\tg.Go(func() error {\n\t\ttime.Sleep(20 * time.Millisecond)\n\t\treturn nil\n\t})\n\n\tif err := g.Wait(); err != nil {\n\t\tfmt.Printf("Перехвачена ошибка группы горутин: %v\\n", err)\n\t} else {\n\t\tfmt.Println("Все задачи завершились успешно")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Перехвачена ошибка группы горутин: ошибка валидации данных пользователя'}], 'under_the_hood': '`g.Wait()` ожидает завершения всех горутин группы и возвращает сохраненную в `once` ошибку.', 'pitfalls': 'Даже если одна горутина вернула ошибку, `g.Wait()` дожидается завершения остальных горутин группы.', 'bigtech_interview': '**Вопрос с собеседования:** «Какую ошибку вернет errgroup.Wait(), если ошибки вернули сразу несколько горутин?»\n**Ответ:** Строго **первую** по времени возврата ошибку, зафиксированную через внутренний `sync.Once`.'}, {'num': 120, 'title': 'Автоматическая каскадная отмена параллельных горутин через errgroup и context', 'task': 'Настройте `errgroup` так, чтобы при возникновении *первой* ошибки все остальные горутины в группе автоматически отменялись (через контекст).', 'theory': 'Связка `errgroup.WithContext(ctx)` создает дочерний контекст, который автоматически отменяется (`cancel()`) в момент, когда любая из горутин группы возвращает ошибку `err != nil`.', 'step_by_step': '1. Создадим отменяемый контекст `context.WithCancel`.\n2. Запустим медленную горутину, слушающую `ctx.Done()`.\n3. Запустим сбойную горутину.\n4. Проверим мгновенную отмену медленной задачи.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype ContextErrGroup struct {\n\tctx    context.Context\n\tcancel context.CancelFunc\n\twg     sync.WaitGroup\n\tonce   sync.Once\n\terr    error\n}\n\nfunc NewContextErrGroup(parent context.Context) (*ContextErrGroup, context.Context) {\n\tctx, cancel := context.WithCancel(parent)\n\treturn &ContextErrGroup{ctx: ctx, cancel: cancel}, ctx\n}\n\nfunc (g *ContextErrGroup) Go(fn func() error) {\n\tg.wg.Add(1)\n\tgo func() {\n\t\tdefer g.wg.Done()\n\t\tif err := fn(); err != nil {\n\t\t\tg.once.Do(func() {\n\t\t\t\tg.err = err\n\t\t\t\tg.cancel() // Мгновенная отмена всех остальных горутин!\n\t\t\t})\n\t\t}\n\t}()\n}\n\nfunc (g *ContextErrGroup) Wait() error {\n\tg.wg.Wait()\n\tg.cancel()\n\treturn g.err\n}\n\nfunc main() {\n\tg, ctx := NewContextErrGroup(context.Background())\n\n\t// Быстрая сбойная задача\n\tg.Go(func() error {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\treturn errors.New("критический сбой в задаче #1")\n\t})\n\n\t// Долгая задача, слушающая отмену контекста\n\tg.Go(func() error {\n\t\tselect {\n\t\tcase <-time.After(2 * time.Second):\n\t\t\tfmt.Println("Задача #2 завершилась")\n\t\t\treturn nil\n\t\tcase <-ctx.Done():\n\t\t\tfmt.Println("[Задача #2] Получен сигнал отмены контекста (ctx.Done), прерываю работу!")\n\t\t\treturn ctx.Err()\n\t\t}\n\t})\n\n\tif err := g.Wait(); err != nil {\n\t\tfmt.Printf("\\n[Main] Группа завершилась с ошибкой: %v\\n", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Задача #2] Получен сигнал отмены контекста (ctx.Done), прерываю работу!\n# \n# [Main] Группа завершилась с ошибкой: критический сбой в задаче #1'}], 'under_the_hood': '`cancel()` закрывает системный канал `ctx.Done()`, прерывая все заблокированные `select` во всех связанных горутинах.', 'pitfalls': 'Горутины обязаны периодически опрашивать `ctx.Done()`, иначе отмена контекста не сможет прервать чистый CPU-цикл.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему errgroup с контекстом предотвращает утечки ресурсов при Fan-Out запросах?»\n**Ответ:** Если один из 10 микросервисов вернул 500 ошибку, отмена контекста немедленно обрывает сетевые соединения остальных 9 запросов, экономя CPU, сокеты и сетевой трафик.'}, {'num': 121, 'title': 'Ограничение параллелизма горутин через лимитер SetLimit в errgroup', 'task': 'Ограничьте максимальное количество параллельных задач в `errgroup` (с помощью `SetLimit`, доступно в свежих версиях пакета).', 'theory': 'Метод `g.SetLimit(n)` задает максимальное количество одновременно работающих горутин (Concurrency Limiter / Worker Pool). Вызов `g.Go()` блокируется, пока одна из активных горутин не завершит работу.', 'step_by_step': '1. Создадим семафор `sem := make(chan struct{}, maxConcurrency)`.\n2. Запустим 10 задач с ограничением не более 2 задач одновременно.\n3. Проследим пачечное выполнение.\n4. Дождемся завершения всех задач.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype LimitedErrGroup struct {\n\twg  sync.WaitGroup\n\tsem chan struct{}\n}\n\nfunc NewLimitedErrGroup(limit int) *LimitedErrGroup {\n\treturn &LimitedErrGroup{\n\t\tsem: make(chan struct{}, limit),\n\t}\n}\n\nfunc (g *LimitedErrGroup) Go(fn func()) {\n\tg.sem <- struct{}{} // Захват слота семафора (блокирует при превышении лимита)\n\tg.wg.Add(1)\n\n\tgo func() {\n\t\tdefer func() {\n\t\t\t<-g.sem // Освобождение слота\n\t\t\tg.wg.Done()\n\t\t}()\n\t\tfn()\n\t}()\n}\n\nfunc (g *LimitedErrGroup) Wait() {\n\tg.wg.Wait()\n}\n\nfunc main() {\n\t// Ограничиваем параллелизм: не более 2 задач одновременно\n\tg := NewLimitedErrGroup(2)\n\n\tfor i := 1; i <= 6; i++ {\n\t\ttaskID := i\n\t\tg.Go(func() {\n\t\t\tfmt.Printf("[Старт] Задача #%d начала выполнение...\\n", taskID)\n\t\t\ttime.Sleep(20 * time.Millisecond)\n\t\t\tfmt.Printf(" -> [Финиш] Задача #%d завершена\\n", taskID)\n\t\t})\n\t}\n\n\tg.Wait()\n\tfmt.Println("Все 6 задач выполнены с ограничением concurrency=2!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод (задачи идут строго парами):\n# [Старт] Задача #1 начала выполнение...\n# [Старт] Задача #2 начала выполнение...\n#  -> [Финиш] Задача #1 завершена\n#  -> [Финиш] Задача #2 завершена\n# [Старт] Задача #3 начала выполнение...\n# [Старт] Задача #4 начала выполнение...\n#  -> [Финиш] Задача #3 завершена\n#  -> [Финиш] Задача #4 завершена\n# [Старт] Задача #5 начала выполнение...\n# [Старт] Задача #6 начала выполнение...\n#  -> [Финиш] Задача #5 завершена\n#  -> [Финиш] Задача #6 завершена\n# Все 6 задач выполнены с ограничением concurrency=2!'}], 'under_the_hood': 'Буферизованный канал `make(chan struct{}, limit)` выполняет роль подсчитывающего семафора Дейкстры.', 'pitfalls': 'Всегда вызывайте `g.SetLimit()` до первого запуска `g.Go()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем ограничивать количество параллельных горутин при парсинге сайтов или миграциях БД?»\n**Ответ:** Чтобы не исчерпать файловые дескрипторы сокетов (ulimit), не положить целевой сервер лавиной запросов (DDoS) и не превысить пул соединений к базе данных.'}, {'num': 122, 'title': 'Высокопроизводительный кэш для Read-Heavy сценариев на базе sync.Map', 'task': 'Используйте `sync.Map` для создания кэша, который оптимизирован для сценариев, где ключи записываются один раз, но читаются множеством горутин (Read-heavy).', 'theory': 'Архитектура `sync.Map` специально спроектирована для неизменяемых или редко обновляемых ключей: чтение происходит через атомарный указатель `atomic.Value` без захвата мьютекса.', 'step_by_step': '1. Создадим структуру `ReadHeavyCache`.\n2. Реализуем методы `Get(key string)` и `Set(key string, val any)`.\n3. Запустим 50 читателей.\n4. Проверим отсутствие блокировок.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype ReadHeavyCache struct {\n\tstore sync.Map\n}\n\nfunc (c *ReadHeavyCache) Get(key string) (any, bool) {\n\treturn c.store.Load(key)\n}\n\nfunc (c *ReadHeavyCache) Set(key string, val any) {\n\tc.store.Store(key, val)\n}\n\nfunc main() {\n\tcache := &ReadHeavyCache{}\n\tcache.Set("app_version", "v2.18.0-release")\n\n\tvar wg sync.WaitGroup\n\tconst readers = 20\n\twg.Add(readers)\n\n\tfor i := 1; i <= readers; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tval, _ := cache.Get("app_version")\n\t\t\tif id == 1 || id == 20 {\n\t\t\t\tfmt.Printf("[Reader #%d] Версия приложения: %v\\n", id, val)\n\t\t\t}\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("Read-heavy кэш на sync.Map отработал идеально!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Reader #1] Версия приложения: v2.18.0-release\n# [Reader #20] Версия приложения: v2.18.0-release\n# Read-heavy кэш на sync.Map отработал идеально!'}], 'under_the_hood': 'Чтение из `read` мапы в `sync.Map` не инвалидирует кэш-линии процессора.', 'pitfalls': 'Значения `any` требуют приведения типов.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему sync.Map называется lock-free при чтении?»\n**Ответ:** Потому что метод `Load` сначала считывает указатель на `read` мапу через `atomic.LoadPointer`. Если ключ найден, его значение извлекается атомарной инструкцией без единого захвата мьютекса.'}, {'num': 123, 'title': 'Сравнительный бенчмарк sync.Map против map + sync.RWMutex в разных сценариях', 'task': 'Сравните производительность `sync.Map` и обычной `map + sync.RWMutex` в разных сценариях.', 'theory': 'Итоговый сравнительный анализ:\n1. Read-Mostly (>90% чтений): `sync.Map` лидирует благодаря отсутствию Cache Contention.\n2. Write-Heavy / Frequent Deletes: `map + sync.RWMutex` быстрее в 2–3 раза.', 'step_by_step': '1. Напишем сводный тест производительности.\n2. Замерим время работы обоих подходов.\n3. Сформулируем инженерные рекомендации по выбору.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tfmt.Println("=== СРАВНИТЕЛЬНЫЙ АНАЛИЗ sync.Map vs map+RWMutex ===")\n\n\t// 1. Тест Read-Heavy\n\tconst ops = 100000\n\tvar sm sync.Map\n\tsm.Store("key", "value")\n\n\tstart := time.Now()\n\tfor i := 0; i < ops; i++ {\n\t\t_, _ = sm.Load("key")\n\t}\n\ttSyncMap := time.Since(start)\n\n\tvar mu sync.RWMutex\n\tm := map[string]string{"key": "value"}\n\tstart = time.Now()\n\tfor i := 0; i < ops; i++ {\n\t\tmu.RLock()\n\t\t_ = m["key"]\n\t\tmu.RUnlock()\n\t}\n\ttRWMutex := time.Since(start)\n\n\tfmt.Printf("1. sync.Map (Lock-Free Read): %v\\n", tSyncMap)\n\tfmt.Printf("2. map + RWMutex (RLock):      %v\\n", tRWMutex)\n\tfmt.Println("\\nРекомендация: Используйте sync.Map для стабильных кэшей метаданных, а map+RWMutex — для динамических коллекций.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === СРАВНИТЕЛЬНЫЙ АНАЛИЗ sync.Map vs map+RWMutex ===\n# 1. sync.Map (Lock-Free Read): 1.45ms\n# 2. map + RWMutex (RLock):      3.12ms\n# \n# Рекомендация: Используйте sync.Map для стабильных кэшей метаданных, а map+RWMutex — для динамических коллекций.'}], 'under_the_hood': '`sm.Load` не модифицирует разделяемые счетчики памяти, масштабируясь на любое число ядер.', 'pitfalls': 'Не оптимизируйте преждевременно: в 95% задач достаточно обычной `map + sync.Mutex`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы главные правила выбора между Mutex, RWMutex, sync.Map и Atomic в Go?»\n**Ответ:** 1) Простой счетчик/флаг $\\to$ `sync/atomic`. 2) Обычная бизнес-структура или мапа $\\to$ `sync.Mutex`. 3) Мапа с редкой записью (90%+ чтение) $\\to$ `sync.RWMutex`. 4) Кэш стабильных ключей под сверхвысокой многоядерной нагрузкой $\\to$ `sync.Map`.'}, {'num': 124, 'title': 'Паттерн Producer-Consumer на базе sync.Cond с оповещениями Signal и Broadcast', 'task': 'Используйте `sync.Cond` для реализации паттерна "Producer-Consumer", где Consumer ждет (Wait), пока Producer не сообщит (Signal/Broadcast) о появлении новых данных.', 'theory': 'Финальный комплексный паттерн главы: многопоточный кольцевой буфер / очередь задач на `sync.Cond` с поддержкой Graceful Shutdown через `Broadcast()`.', 'step_by_step': '1. Создадим структуру `SafeQueue` с `sync.Mutex`, `*sync.Cond` и флагом закрытия `closed`.\n2. Реализуем метод `Push(item string)` с `cond.Signal()`.\n3. Реализуем метод `Pop() (string, bool)` с `cond.Wait()`.\n4. Реализуем метод `Close()` с `cond.Broadcast()`.\n5. Протестируем работу 2 потребителей и корректное завершение.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype SafeQueue struct {\n\tmu     sync.Mutex\n\tcond   *sync.Cond\n\titems  []string\n\tclosed bool\n}\n\nfunc NewSafeQueue() *SafeQueue {\n\tq := &SafeQueue{}\n\tq.cond = sync.NewCond(&q.mu)\n\treturn q\n}\n\nfunc (q *SafeQueue) Push(val string) {\n\tq.mu.Lock()\n\tdefer q.mu.Unlock()\n\n\tif q.closed {\n\t\treturn\n\t}\n\tq.items = append(q.items, val)\n\tq.cond.Signal() // Будим одного потребителя\n}\n\nfunc (q *SafeQueue) Pop() (string, bool) {\n\tq.mu.Lock()\n\tdefer q.mu.Unlock()\n\n\tfor len(q.items) == 0 && !q.closed {\n\t\tq.cond.Wait()\n\t}\n\n\tif len(q.items) == 0 && q.closed {\n\t\treturn "", false // Очередь закрыта и пуста\n\t}\n\n\tval := q.items[0]\n\tq.items = q.items[1:]\n\treturn val, true\n}\n\nfunc (q *SafeQueue) Close() {\n\tq.mu.Lock()\n\tdefer q.mu.Unlock()\n\n\tq.closed = true\n\tq.cond.Broadcast() // Будим ВСЕХ потребителей для завершения\n}\n\nfunc main() {\n\tqueue := NewSafeQueue()\n\tvar wg sync.WaitGroup\n\n\t// Запуск 2 потребителей (Consumers)\n\tfor c := 1; c <= 2; c++ {\n\t\twg.Add(1)\n\t\tgo func(consumerID int) {\n\t\t\tdefer wg.Done()\n\t\t\tfor {\n\t\t\t\titem, ok := queue.Pop()\n\t\t\t\tif !ok {\n\t\t\t\t\tfmt.Printf("[Consumer #%d] Очередь закрыта, завершаю работу\\n", consumerID)\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\tfmt.Printf(" -> [Consumer #%d] Успешно обработал: %s\\n", consumerID, item)\n\t\t\t}\n\t\t}(c)\n\t}\n\n\t// Поставщик (Producer) добавляет сообщения\n\tqueue.Push("Event: UserRegistered")\n\tqueue.Push("Event: OrderPaid")\n\tqueue.Push("Event: EmailSent")\n\n\ttime.Sleep(20 * time.Millisecond)\n\n\t// Graceful Shutdown\n\tfmt.Println("\\n[Main] Завершение работы: отправка Close() и Broadcast()...")\n\tqueue.Close()\n\n\twg.Wait()\n\tfmt.Println("[Main] Все потребители корректно завершили работу. Глава 20 освоена на 100%!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n#  -> [Consumer #1] Успешно обработал: Event: UserRegistered\n#  -> [Consumer #2] Успешно обработал: Event: OrderPaid\n#  -> [Consumer #1] Успешно обработал: Event: EmailSent\n# \n# [Main] Завершение работы: отправка Close() и Broadcast()...\n# [Consumer #2] Очередь закрыта, завершаю работу\n# [Consumer #1] Очередь закрыта, завершаю работу\n# [Main] Все потребители корректно завершили работу. Глава 20 освоена на 100%!'}], 'under_the_hood': '`Close()` переводит флаг `closed = true` и будит всех потребителей через `cond.Broadcast()`, позволяя горутинам выйти из цикла ожидания без дедлока.', 'pitfalls': 'Всегда проверяйте `!q.closed` в условии цикла ожидания `for len(q.items) == 0 && !q.closed { cond.Wait() }`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать Graceful Shutdown для пула воркеров на sync.Cond?»\n**Ответ:** Установить флаг `closed = true` под мьютексом и вызвать `cond.Broadcast()`. Все спящие воркеры проснутся, проверят условие `len(items) == 0 && closed`, корректно завершат метод и выйдут из горутины.'}]
